class ArchiveCliTests(unittest.TestCase):
    def setUp(self) -> None:
        exact_write_patcher = patch.object(
            archive_cli,
            "_execute_exact_human_approved_write",
            side_effect=self.execute_test_exact_human_write,
        )
        exact_write_patcher.start()
        self.addCleanup(exact_write_patcher.stop)
        link_exact_write_patcher = patch.object(
            archive_cli,
            "_execute_zettel_objet_link_exact_human_approved_write",
            side_effect=self.execute_test_exact_human_write,
        )
        link_exact_write_patcher.start()
        self.addCleanup(link_exact_write_patcher.stop)
        # Production approval intentionally fails closed outside Windows.
        # Cross-platform CI still exercises the approval transaction algorithm
        # under a test-only capability injection; the dedicated platform test
        # patches this back to False and owns the real POSIX UX contract.
        if os.name != "nt":
            platform_patcher = patch.object(
                archive_services,
                "WOM_KIT_PROJECT_UPDATE_APPROVAL_PLATFORM_SUPPORTED",
                True,
            )
            platform_patcher.start()
            self.addCleanup(platform_patcher.stop)

    def run_cli(self, args: list[str], stdin_text: str | None = None) -> tuple[int, str]:
        buffer = io.StringIO()
        old_stdin = sys.stdin
        if stdin_text is not None:
            sys.stdin = io.StringIO(stdin_text)
        try:
            with redirect_stdout(buffer), redirect_stderr(buffer):
                code = archive_cli.main(args)
            return code, buffer.getvalue()
        finally:
            sys.stdin = old_stdin

    @staticmethod
    def execute_test_exact_human_write(root, context, writer):
        """Exercise a CLI writer through a real authenticated claim, without UI."""

        claim = claim_exact_human_approval(
            root,
            context,
            ExactHumanApprovalDecision(
                approved=True,
                synthetic_acknowledged=False,
                reason_code="exact_human_approval_approved",
                plan_sha256=context.plan_sha256,
                target_binding_sha256=context.target_binding_sha256,
            ),
            bytearray(b"c" * 32),
        )
        try:
            reference = claim.assert_ready_for_context(context)
            result = dict(writer(claim))
            if result.get("ok") is True:
                claim.finalize_succeeded()
            else:
                result["exact_human_approval_reconciliation"] = {
                    "required": True,
                    "reason_code": "approval_claim_reconciliation_required",
                    "automatic_retry_allowed": False,
                }
            result["exact_human_approval"] = claim.public_summary()
            result["exact_human_approval_reference"] = reference
            return result
        finally:
            claim.close()

    def run_cli_split(self, args: list[str]) -> tuple[int, str, str]:
        stdout = io.StringIO()
        stderr = io.StringIO()
        with redirect_stdout(stdout), redirect_stderr(stderr):
            code = archive_cli.main(args)
        return code, stdout.getvalue(), stderr.getvalue()

    def manifest_source_fidelity_fixture(
        self,
        archive_root: Path,
        source_text: str,
    ) -> str:
        raw = source_text.encode("utf-8")
        digest = hashlib.sha256(raw).hexdigest()
        object_id = f"sha256:{digest}"
        logical_key = f"objects/sha256/{digest[:2]}/{digest}"
        object_path = archive_root.joinpath(*logical_key.split("/"))
        object_path.parent.mkdir(parents=True, exist_ok=True)
        object_path.write_bytes(raw)

        manifest_path = archive_root / "objects" / "manifests" / "files.jsonl"
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        existing_text = (
            manifest_path.read_text(encoding="utf-8")
            if manifest_path.exists()
            else ""
        )
        records = [
            json.loads(line)
            for line in existing_text.splitlines()
            if line.strip()
        ]
        if not any(record.get("object_id") == object_id for record in records):
            separator = "" if not existing_text or existing_text.endswith("\n") else "\n"
            record = {
                "object_id": object_id,
                "sha256": digest,
                "logical_key": logical_key,
                "mime": "text/plain",
                "size_bytes": len(raw),
                "locations": [
                    {
                        "provider": "local",
                        "path": logical_key,
                        "availability": "available",
                    }
                ],
                "provenance": {
                    "created_in": archive_services.read_archive_config(archive_root)[
                        "archive_id"
                    ],
                    "source": "source_fidelity_test_fixture",
                },
            }
            manifest_path.write_text(
                existing_text
                + separator
                + json.dumps(record, sort_keys=True, separators=(",", ":"))
                + "\n",
                encoding="utf-8",
            )
        return object_id

    def install_historical_draft_from_preview(
        self,
        archive_root: Path,
        preview: dict[str, Any],
        *,
        body: str,
    ) -> dict[str, Any]:
        """Install a bounded pre-v0.4 draft fixture from a read-only preview."""

        self.assertTrue(preview.get("ok"), preview)
        self.assertTrue(preview.get("dry_run"), preview)
        relative_path = preview.get("proposed_path")
        frontmatter = preview.get("frontmatter_preview")
        self.assertIsInstance(relative_path, str)
        self.assertIsInstance(frontmatter, dict)
        assert isinstance(relative_path, str)
        assert isinstance(frontmatter, dict)
        relative = PurePosixPath(relative_path)
        self.assertFalse(relative.is_absolute())
        self.assertEqual(relative.parts[0], "inbox")
        self.assertEqual(relative.suffix, ".md")
        root = archive_root.resolve()
        destination = root.joinpath(*relative.parts).resolve()
        self.assertEqual(os.path.commonpath([str(root), str(destination)]), str(root))
        destination.parent.mkdir(parents=True, exist_ok=True)
        self.assertFalse(destination.exists())
        destination.write_text(
            "---\n"
            + archive_cli.dump_yaml(copy.deepcopy(frontmatter))
            + "---\n\n"
            + body.rstrip()
            + "\n",
            encoding="utf-8",
        )
        return {
            "ok": True,
            "dry_run": False,
            "lifecycle_action": "create_draft",
            "zettel_id": frontmatter["id"],
            "path": relative.as_posix(),
            "status": "draft",
            "frontmatter": copy.deepcopy(frontmatter),
            "first_read_check": copy.deepcopy(preview.get("first_read_check")),
            "warnings": copy.deepcopy(preview.get("warnings", [])),
        }

