    def create_abstract_backfill_proposal(
        self,
        archive_root: Path,
        *,
        count: int = 1,
        name: str = "reviewed.jsonl",
    ) -> dict[str, Any]:
        zettel_paths = sorted((archive_root / "zettels").glob("*.md"))[:count]
        self.assertEqual(len(zettel_paths), count)
        rows: list[dict[str, Any]] = []
        originals: dict[Path, bytes] = {}
        abstracts: list[str] = []
        for index, zettel_path in enumerate(zettel_paths):
            original = zettel_path.read_bytes()
            abstract = f"PRIVATE HUMAN REVIEWED ABSTRACT {index + 1}"
            originals[zettel_path] = original
            abstracts.append(abstract)
            rows.append(
                {
                    "schema": "wom-kit/zet-abstract-backfill-proposal/v0.1",
                    "zettel_id": archive_services.read_zettel_frontmatter_only(zettel_path)["id"],
                    "expected_file_sha256": "sha256:" + hashlib.sha256(original).hexdigest(),
                    "abstract": abstract,
                    "generation_mode": "ai_assisted" if index % 2 == 0 else "human_written",
                    "basis": "canonical_zet_body",
                }
            )
        relative = f".wom-scratch/abstract-backfill/{name}"
        proposal_path = archive_root / relative
        proposal_path.parent.mkdir(parents=True, exist_ok=True)
        proposal_path.write_text(
            "".join(json.dumps(row, ensure_ascii=False) + "\n" for row in rows),
            encoding="utf-8",
        )
        return {
            "relative": relative,
            "path": proposal_path,
            "sha256": "sha256:" + hashlib.sha256(proposal_path.read_bytes()).hexdigest(),
            "rows": rows,
            "originals": originals,
            "abstracts": abstracts,
        }

    def install_historical_abstract_backfill_applied_fixture(
        self,
        archive_root: Path,
        *,
        count: int = 1,
        name: str = "historical-reviewed.jsonl",
    ) -> dict[str, Any]:
        """Install one bounded pre-v0.4 applied receipt for read/audit tests."""

        fixture = self.create_abstract_backfill_proposal(
            archive_root,
            count=count,
            name=name,
        )
        plan = archive_services.zet_abstract_backfill_plan(
            archive_root,
            proposal_path=fixture["relative"],
            max_items=count,
            dry_run=True,
        )
        self.assertTrue(plan["ok"], plan)
        candidates, blockers = archive_services.materialize_zet_abstract_backfill_candidates(
            archive_root,
            fixture["path"].read_bytes(),
            plan,
        )
        self.assertEqual(blockers, [])
        self.assertEqual(len(candidates), count)
        for candidate in candidates:
            candidate["path"].write_bytes(
                archive_services.zet_abstract_backfill_candidate_bytes(
                    candidate["before_bytes"],
                    candidate["abstract"],
                )
            )

        receipt_relative = archive_services.zet_abstract_backfill_receipt_relative_path(
            fixture["sha256"]
        )
        receipt = {
            "schema": archive_services.ZET_ABSTRACT_BACKFILL_RECEIPT_SCHEMA,
            "action": "zet_abstract_backfill_write",
            "status": "applied",
            "applied_at": "2026-08-19T00:00:00Z",
            "archive_id": archive_services.read_archive_id(archive_root),
            "proposal_sha256": fixture["sha256"],
            "plan_digest": plan["plan_digest"],
            "reviewed_by": "person:historical-abstract-reviewer",
            "human_affirmation": "all_proposed_abstracts_reviewed",
            "item_count": len(candidates),
            "items": [
                {
                    "row_index": candidate["row_index"],
                    "zettel_id": candidate["zettel_id"],
                    "canonical_path": candidate["relative_path"],
                    "generation_mode": candidate["generation_mode"],
                    "before_file_sha256": candidate["before_file_sha256"],
                    "after_file_sha256": candidate["after_file_sha256"],
                    "abstract_sha256": candidate["abstract_sha256"],
                    "body_sha256": candidate["body_sha256"],
                }
                for candidate in candidates
            ],
            "mutation_contract": {
                "field_added": "frontmatter.abstract",
                "body_bytes_preserved": True,
                "other_frontmatter_semantics_preserved": True,
                "updated_at_changed": False,
                "rollback_on_runtime_failure": True,
                "crash_recovery_journal_written": True,
            },
            "privacy_guards": {
                "abstract_text_stored_in_receipt": False,
                "body_text_stored_in_receipt": False,
                "provider_api_called": False,
                "model_called": False,
                "secret_store_or_environment_read": False,
            },
        }
        self.assertEqual(
            archive_services.validate_schema(
                receipt,
                "zet-abstract-backfill-receipt.schema.json",
            ),
            [],
        )
        receipt_path = archive_root / Path(receipt_relative)
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        receipt_path.write_text(
            json.dumps(receipt, indent=2, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
        return {
            **fixture,
            "plan": plan,
            "candidates": candidates,
            "receipt": receipt,
            "receipt_relative": receipt_relative,
            "receipt_path": receipt_path,
            "receipt_sha256": "sha256:"
            + hashlib.sha256(receipt_path.read_bytes()).hexdigest(),
        }

