    def install_historical_abstract_backfill_transaction_journal(
        self,
        archive_root: Path,
        fixture: dict[str, Any],
        *,
        operation: str,
        reviewed_by: str,
    ) -> Path:
        """Install bounded pre-v0.4 transaction residue for recovery/audit tests."""

        if operation == "apply":
            basis_kind = "proposal"
            basis_sha256 = fixture["sha256"]
            final_receipt_path = fixture["receipt_relative"]
            human_affirmation = "all_proposed_abstracts_reviewed"
            suffix = "write"
            items = [
                {
                    "row_index": candidate["row_index"],
                    "zettel_id": candidate["zettel_id"],
                    "canonical_path": candidate["relative_path"],
                    "generation_mode": candidate["generation_mode"],
                    "before_file_sha256": candidate["before_file_sha256"],
                    "after_file_sha256": candidate["after_file_sha256"],
                    "abstract_sha256": candidate["abstract_sha256"],
                    "body_sha256": candidate["body_sha256"],
                }
                for candidate in fixture["candidates"]
            ]
        elif operation == "revert":
            basis_kind = "source_receipt"
            basis_sha256 = fixture["receipt_sha256"]
            final_receipt_path = fixture["revert_receipt_relative"]
            human_affirmation = "abstract_removal_reviewed"
            suffix = "abstract-revert"
            items = [
                {
                    "row_index": candidate["row_index"],
                    "zettel_id": candidate["zettel_id"],
                    "canonical_path": candidate["relative_path"],
                    "generation_mode": candidate["generation_mode"],
                    "before_file_sha256": candidate["after_file_sha256"],
                    "after_file_sha256": candidate["before_file_sha256"],
                    "abstract_sha256": candidate["abstract_sha256"],
                    "body_sha256": candidate["body_sha256"],
                }
                for candidate in fixture["candidates"]
            ]
        else:
            raise AssertionError(f"unsupported historical operation: {operation}")

        journal = archive_services.zet_abstract_backfill_transaction_journal_document(
            operation=operation,
            prepared_at="2026-08-19T00:00:30Z",
            archive_id=archive_services.read_archive_id(archive_root),
            transaction_basis_kind=basis_kind,
            transaction_basis_sha256=basis_sha256,
            plan_digest=fixture["plan"]["plan_digest"],
            reviewed_by=reviewed_by,
            human_affirmation=human_affirmation,
            final_receipt_path=final_receipt_path,
            items=items,
        )
        self.assertEqual(
            archive_services.validate_schema(
                journal,
                "zet-abstract-backfill-transaction-journal.schema.json",
            ),
            [],
        )
        digest = basis_sha256.removeprefix("sha256:")
        journal_path = (
            archive_root
            / ".wom-scratch"
            / "abstract-backfill"
            / f".{digest}.{suffix}.transaction.json"
        )
        journal_path.parent.mkdir(parents=True, exist_ok=True)
        journal_path.write_text(
            json.dumps(journal, indent=2, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
        return journal_path

    def create_zet_revision_proposal(
        self,
        archive_root: Path,
        *,
        name: str = "private-reviewed-revision.md",
        title_marker: str = "PRIVATE_REVISED_TITLE",
        abstract_marker: str = "PRIVATE_REVISED_ABSTRACT",
        body_marker: str = "PRIVATE_REVISED_BODY",
    ) -> dict[str, Any]:
        canonical_path = sorted((archive_root / "zettels").glob("*.md"))[0]
        frontmatter, body = archive_services.split_zettel_text(
            canonical_path.read_text(encoding="utf-8")
        )
        frontmatter["abstract"] = "Current reviewed first read."
        canonical_path.write_text(
            "---\n" + archive_cli.dump_yaml(frontmatter) + "---\n\n" + body.rstrip() + "\n",
            encoding="utf-8",
        )
        original_bytes = canonical_path.read_bytes()
        proposed_frontmatter = json.loads(json.dumps(frontmatter))
        proposed_frontmatter["title"] = title_marker
        proposed_frontmatter["abstract"] = abstract_marker
        proposal_relative = f".wom-scratch/revisions/{name}"
        proposal_path = archive_root / proposal_relative
        proposal_path.parent.mkdir(parents=True, exist_ok=True)
        proposal_path.write_text(
            "---\n"
            + archive_cli.dump_yaml(proposed_frontmatter)
            + "---\n\n"
            + body.rstrip()
            + f"\n\n{body_marker}\n",
            encoding="utf-8",
        )
        plan = archive_services.zet_revision_plan(
            archive_root,
            zettel_id=frontmatter["id"],
            proposal_path=proposal_relative,
            dry_run=True,
        )
        self.assertTrue(plan["ok"], plan)
        return {
            "canonical_path": canonical_path,
            "original_bytes": original_bytes,
            "zettel_id": frontmatter["id"],
            "proposal_relative": proposal_relative,
            "proposal_path": proposal_path,
            "plan": plan,
            "title_marker": title_marker,
            "abstract_marker": abstract_marker,
            "body_marker": body_marker,
        }

    def approve_zet_revision_fixture(
        self,
        archive_root: Path,
        fixture: dict[str, Any],
        *,
        revision_at: str,
        reviewed_by: str = "person:fake-reviewer",
    ) -> dict[str, Any]:
        """Install one bounded historical revision without its blocked writer."""

        plan = fixture["plan"]
        base = {
            "zettel_id": fixture["zettel_id"],
            "proposal_path": fixture["proposal_relative"],
            "expected_canonical_sha256": plan["canonical"]["sha256"],
            "expected_proposal_sha256": plan["proposal"]["sha256"],
            "expected_proposal_semantic_sha256": plan["proposal"][
                "semantic_sha256"
            ],
            "expected_plan_digest": plan["plan_digest"],
            "revision_at": revision_at,
        }
        preview = archive_services.zet_revision_write(
            archive_root, **base, dry_run=True
        )
        self.assertTrue(preview["ok"], preview)
        canonical_path = fixture["canonical_path"]
        canonical_bytes = canonical_path.read_bytes()
        current_frontmatter, current_body = archive_services.split_zettel_text(
            archive_services.decode_utf8_with_universal_newlines(
                canonical_bytes
            )
        )
        proposed_frontmatter, proposed_body = archive_services.split_zettel_text(
            fixture["proposal_path"].read_text(encoding="utf-8")
        )
        candidate = archive_services.zet_revision_candidate_material(
            current_frontmatter,
            current_body,
            proposed_frontmatter,
            proposed_body,
            revision_at=revision_at,
        )
        change_summary = plan["change_summary"]
        canonical_relative = archive_services.archive_relative_path(
            canonical_path,
            archive_root,
        )
        write_plan_digest = archive_services.zet_revision_write_plan_digest(
            archive_id=archive_services.read_archive_id(archive_root),
            zettel_id=fixture["zettel_id"],
            canonical_path=canonical_relative,
            canonical_sha256=plan["canonical"]["sha256"],
            proposal_sha256=plan["proposal"]["sha256"],
            proposal_semantic_sha256=plan["proposal"]["semantic_sha256"],
            plan_digest=plan["plan_digest"],
            revision_at=revision_at,
            candidate=candidate,
            change_summary=change_summary,
        )
        self.assertEqual(
            preview["write_plan"]["actual_digest"], write_plan_digest
        )

        snapshot = archive_services.zet_revision_before_snapshot_descriptor(
            canonical_bytes
        )
        snapshot_path = archive_root.joinpath(
            *Path(snapshot["logical_key"]).parts
        )
        snapshot_path.parent.mkdir(parents=True, exist_ok=True)
        if snapshot_path.exists():
            self.assertEqual(snapshot_path.read_bytes(), canonical_bytes)
        else:
            snapshot_path.write_bytes(canonical_bytes)

        manifest_path = archive_root / "objects" / "manifests" / "files.jsonl"
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        existing_records = [
            json.loads(line)
            for line in (
                manifest_path.read_text(encoding="utf-8").splitlines()
                if manifest_path.exists()
                else []
            )
            if line.strip()
        ]
        if not any(
            record.get("object_id") == snapshot["object_id"]
            and record.get("logical_key") == snapshot["logical_key"]
            for record in existing_records
            if isinstance(record, dict)
        ):
            manifest_record = {
                "object_id": snapshot["object_id"],
                "sha256": snapshot["object_id"].removeprefix("sha256:"),
                "logical_key": snapshot["logical_key"],
                "mime": "text/markdown",
                "size_bytes": len(canonical_bytes),
                "locations": [
                    {
                        "provider": "local",
                        "path": snapshot["logical_key"],
                        "availability": "available",
                    }
                ],
                "provenance": {
                    "created_in": (
                        "archive:"
                        + archive_services.read_archive_id(archive_root)
                    ),
                    "source": "canonical_zet_before_revision",
                    "captured_at": revision_at,
                    "captured_by": reviewed_by,
                    "revision_write_plan_digest": write_plan_digest,
                },
            }
            existing = (
                manifest_path.read_text(encoding="utf-8")
                if manifest_path.exists()
                else ""
            )
            separator = "" if not existing or existing.endswith("\n") else "\n"
            manifest_path.write_text(
                existing
                + separator
                + json.dumps(
                    manifest_record,
                    ensure_ascii=False,
                    separators=(",", ":"),
                )
                + "\n",
                encoding="utf-8",
            )

        lock_basis = {
            "schema": archive_services.ZET_REVISION_WRITE_LOCK_SCHEMA,
            "archive_id": archive_services.read_archive_id(archive_root),
            "zettel_id": fixture["zettel_id"],
            "canonical_path": canonical_relative,
            "canonical_sha256": plan["canonical"]["sha256"],
            "proposal_sha256": plan["proposal"]["sha256"],
            "proposal_semantic_sha256": plan["proposal"]["semantic_sha256"],
            "plan_digest": plan["plan_digest"],
            "write_plan_digest": write_plan_digest,
            "candidate_file_sha256": candidate["file_sha256"],
            "candidate_semantic_sha256": candidate["semantic_sha256"],
            "before_semantic_sha256": candidate["before_semantic_sha256"],
            "before_abstract_sha256": candidate["before_abstract_sha256"],
            "before_body_sha256": candidate["before_body_sha256"],
            "candidate_abstract_sha256": candidate["after_abstract_sha256"],
            "candidate_body_sha256": candidate["after_body_sha256"],
            "revision_at": revision_at,
            "reviewed_by": reviewed_by,
            "human_review": {
                "revision_reviewed": True,
                "abstract_body_pair_reviewed": True,
                "edge_review_required": bool(
                    change_summary.get("edges_changed")
                ),
                "edge_changes_reviewed": bool(
                    change_summary.get("edges_changed")
                ),
            },
            "change_summary": change_summary,
            "before_snapshot": snapshot,
        }
        receipt = archive_services.zet_revision_receipt_from_lock(
            lock_basis,
            transaction_started_at=revision_at,
            resumed_from_existing_lock=False,
            finalized_from_already_written_candidate=False,
        )
        self.assertEqual(
            archive_services.validate_schema(
                receipt,
                "zet-revision-receipt-v0.2.schema.json",
            ),
            [],
        )
        receipt_relative = archive_services.zet_revision_receipt_relative_path(
            write_plan_digest
        )
        receipt_path = archive_root.joinpath(*Path(receipt_relative).parts)
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        self.assertFalse(receipt_path.exists())
        canonical_path.write_bytes(candidate["bytes"])
        receipt_path.write_text(
            json.dumps(receipt, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        applied = {
            "ok": True,
            "status": "applied",
            "approved": True,
            "canonical": {
                "candidate_file_sha256": candidate["file_sha256"],
                "candidate_semantic_sha256": candidate["semantic_sha256"],
            },
            "write_boundary": {
                "canonical_files_written_this_run": 1,
            },
            "receipt": {
                "path": receipt_relative,
                "exists": True,
                "written_this_run": True,
                "sha256": "sha256:"
                + hashlib.sha256(receipt_path.read_bytes()).hexdigest(),
            },
            "before_snapshot": {
                **snapshot,
                "verified": True,
                "bytes_written_this_run": 1,
                "manifest_records_appended_this_run": 1,
            },
            "privacy_guards": {"zettel_id_echoed": False},
        }
        return {"preview": preview, "applied": applied, "arguments": base}

    def create_zet_revision_restore_fixture(
        self,
        archive_root: Path,
        *,
        source_revision_at: str = "2026-07-14T16:00:00Z",
        restore_name: str = "private-exact-restore.md",
    ) -> dict[str, Any]:
        revision_fixture = self.create_zet_revision_proposal(archive_root)
        applied_bundle = self.approve_zet_revision_fixture(
            archive_root,
            revision_fixture,
            revision_at=source_revision_at,
        )
        receipt_relative = applied_bundle["applied"]["receipt"]["path"]
        receipt_path = archive_root / receipt_relative
        receipt_bytes = receipt_path.read_bytes()
        receipt_sha256 = "sha256:" + hashlib.sha256(receipt_bytes).hexdigest()
        restore_relative = f".wom-scratch/revisions/restores/{restore_name}"
        restore_path = archive_root / restore_relative
        restore_path.parent.mkdir(parents=True, exist_ok=True)
        restore_path.write_bytes(revision_fixture["original_bytes"])
        restore_plan = archive_services.zet_revision_restore_plan(
            archive_root,
            receipt_path=receipt_relative,
            expected_receipt_sha256=receipt_sha256,
            restore_proposal_path=restore_relative,
            dry_run=True,
        )
        self.assertTrue(restore_plan["ok"], restore_plan)
        return {
            "revision_fixture": revision_fixture,
            "applied_bundle": applied_bundle,
            "receipt_relative": receipt_relative,
            "receipt_path": receipt_path,
            "receipt_bytes": receipt_bytes,
            "receipt_sha256": receipt_sha256,
            "restore_relative": restore_relative,
            "restore_path": restore_path,
            "restore_plan": restore_plan,
        }

    def install_historical_zet_revision_restore_fixture(
        self,
        archive_root: Path,
        fixture: dict[str, Any],
        *,
        revision_at: str,
        reviewed_by: str = "person:fake-restore-reviewer",
    ) -> dict[str, Any]:
        """Install one bounded historical restore without its blocked writer."""

        restore_plan = fixture["restore_plan"]
        base = {
            "receipt_path": fixture["receipt_relative"],
            "expected_receipt_sha256": fixture["receipt_sha256"],
            "restore_proposal_path": fixture["restore_relative"],
            "expected_current_sha256": restore_plan["current"]["state"][
                "file_sha256"
            ],
            "expected_restore_proposal_sha256": restore_plan[
                "restore_proposal"
            ]["state"]["file_sha256"],
            "expected_restore_proposal_semantic_sha256": restore_plan[
                "restore_proposal"
            ]["state"]["semantic_sha256"],
            "expected_restore_plan_digest": restore_plan["plan_digest"],
            "revision_at": revision_at,
        }
        preview = archive_services.zet_revision_restore_write(
            archive_root, **base, dry_run=True
        )
        self.assertTrue(preview["ok"], preview)
        write_plan_digest = preview["write_plan"]["actual_digest"]
        self.assertRegex(write_plan_digest, r"^sha256:[0-9a-f]{64}$")

        source_receipt = json.loads(
            fixture["receipt_path"].read_text(encoding="utf-8")
        )
        canonical_path = fixture["revision_fixture"]["canonical_path"]
        canonical_relative = archive_services.archive_relative_path(
            canonical_path, archive_root
        )
        current_state = restore_plan["current"]["state"]
        candidate_state = restore_plan["restore_proposal"]["state"]
        candidate_bytes = fixture["restore_path"].read_bytes()
        self.assertEqual(
            "sha256:" + hashlib.sha256(canonical_path.read_bytes()).hexdigest(),
            current_state["file_sha256"],
        )
        self.assertEqual(
            "sha256:" + hashlib.sha256(candidate_bytes).hexdigest(),
            candidate_state["file_sha256"],
        )
        change_summary = preview["write_plan"]["change_summary"]
        lock_basis = {
            "schema": archive_services.ZET_REVISION_RESTORE_WRITE_LOCK_SCHEMA,
            "archive_id": archive_services.read_archive_id(archive_root),
            "zettel_id": fixture["revision_fixture"]["zettel_id"],
            "canonical_path": canonical_relative,
            "canonical_sha256": current_state["file_sha256"],
            "source_receipt_sha256": fixture["receipt_sha256"],
            "source_write_plan_digest": source_receipt["write_plan_digest"],
            "proposal_sha256": candidate_state["file_sha256"],
            "proposal_semantic_sha256": candidate_state["semantic_sha256"],
            "plan_digest": restore_plan["plan_digest"],
            "history_audit_digest": preview["restore_plan"][
                "history_audit_digest"
            ],
            "write_plan_digest": write_plan_digest,
            "candidate_file_sha256": candidate_state["file_sha256"],
            "candidate_semantic_sha256": candidate_state["semantic_sha256"],
            "before_semantic_sha256": current_state["semantic_sha256"],
            "before_abstract_sha256": current_state["abstract_sha256"],
            "before_body_sha256": current_state["body_sha256"],
            "candidate_abstract_sha256": candidate_state["abstract_sha256"],
            "candidate_body_sha256": candidate_state["body_sha256"],
            "revision_at": revision_at,
            "reviewed_by": reviewed_by,
            "human_review": {
                "restore_reviewed": True,
                "abstract_body_pair_reviewed": True,
                "edge_review_required": bool(
                    change_summary.get("edges_changed")
                ),
                "edge_changes_reviewed": bool(
                    change_summary.get("edges_changed")
                ),
            },
            "change_summary": change_summary,
        }
        receipt = archive_services.zet_revision_restore_receipt_from_lock(
            lock_basis,
            transaction_started_at=revision_at,
            resumed_from_existing_lock=False,
            finalized_from_already_written_candidate=False,
        )
        self.assertEqual(
            archive_services.validate_schema(
                receipt, "zet-revision-restore-receipt.schema.json"
            ),
            [],
        )
        receipt_relative = archive_services.zet_revision_receipt_relative_path(
            write_plan_digest
        )
        receipt_path = archive_root.joinpath(*Path(receipt_relative).parts)
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        self.assertFalse(receipt_path.exists())
        source_receipt_bytes = fixture["receipt_path"].read_bytes()
        canonical_path.write_bytes(candidate_bytes)
        receipt_path.write_text(
            json.dumps(receipt, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        self.assertEqual(fixture["receipt_path"].read_bytes(), source_receipt_bytes)
        applied = {
            "ok": True,
            "status": "applied",
            "approved": True,
            "receipt": {
                "path": receipt_relative,
                "exists": True,
                "written_this_run": True,
                "sha256": "sha256:"
                + hashlib.sha256(receipt_path.read_bytes()).hexdigest(),
            },
            "write_boundary": {"canonical_files_written_this_run": 1},
        }
        return {"preview": preview, "applied": applied, "arguments": base}

    def install_historical_zet_revision_lock_fixture(
        self,
        archive_root: Path,
        fixture: dict[str, Any],
        *,
        revision_at: str,
        state: str,
    ) -> dict[str, Any]:
        """Install a bounded historical prewrite/recovery/completed lock."""

        if state not in {"prewrite", "missing_receipt", "completed"}:
            raise AssertionError(f"unsupported historical lock state: {state}")
        bundle = self.approve_zet_revision_fixture(
            archive_root,
            fixture,
            revision_at=revision_at,
        )
        applied = bundle["applied"]
        receipt_path = archive_root / applied["receipt"]["path"]
        receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
        lock_document = {
            "schema": archive_services.ZET_REVISION_WRITE_LOCK_SCHEMA,
            "archive_id": receipt["archive_id"],
            "zettel_id": receipt["zettel_id"],
            "canonical_path": receipt["canonical_path"],
            "canonical_sha256": receipt["before"]["file_sha256"],
            "proposal_sha256": receipt["proposal_sha256"],
            "proposal_semantic_sha256": receipt["proposal_semantic_sha256"],
            "plan_digest": receipt["plan_digest"],
            "write_plan_digest": receipt["write_plan_digest"],
            "candidate_file_sha256": receipt["after"]["file_sha256"],
            "candidate_semantic_sha256": receipt["after"]["semantic_sha256"],
            "before_semantic_sha256": receipt["before"]["semantic_sha256"],
            "before_abstract_sha256": receipt["before"]["abstract_sha256"],
            "before_body_sha256": receipt["before"]["body_sha256"],
            "candidate_abstract_sha256": receipt["after"]["abstract_sha256"],
            "candidate_body_sha256": receipt["after"]["body_sha256"],
            "revision_at": receipt["revision_at"],
            "reviewed_by": receipt["reviewed_by"],
            "human_review": receipt["human_review"],
            "change_summary": receipt["change_summary"],
            "before_snapshot": receipt["before_snapshot"],
            "transaction_started_at": receipt["applied_at"],
        }
        lock_path = archive_services.zet_revision_write_lock_path(
            archive_root,
            archive_id=receipt["archive_id"],
            zettel_id=receipt["zettel_id"],
        )
        lock_path.parent.mkdir(parents=True, exist_ok=True)
        lock_path.write_text(
            json.dumps(lock_document, ensure_ascii=False, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        if state == "prewrite":
            fixture["canonical_path"].write_bytes(fixture["original_bytes"])
        if state != "completed":
            receipt_path.unlink()
        return {
            "bundle": bundle,
            "lock_path": lock_path,
            "lock_document": lock_document,
            "receipt_path": receipt_path,
        }

    def assert_compound_revision_write_blocked(
        self,
        result: dict[str, Any],
        *,
        lifecycle_action: str,
    ) -> None:
        self.assertFalse(result["ok"], result)
        self.assertEqual(result["state"], "blocked")
        self.assertEqual(result["status"], "blocked")
        self.assertEqual(result["write_status"], "blocked")
        self.assertEqual(result["lifecycle_action"], lifecycle_action)
        self.assertEqual(
            result["blockers"],
            ["compound_exact_human_approval_binding_required"],
        )
        self.assertEqual(result["files_written"], [])
        self.assertFalse(result["private_values_echoed"])

    def assert_cli_compound_writer_fails_closed(
        self,
        archive_root: Path,
        arguments: list[str],
        *,
        lifecycle_action: str,
    ) -> dict[str, Any]:
        before = self.archive_tree_snapshot(archive_root)
        code, output = self.run_cli([*arguments, "--format", "json"])
        self.assertEqual(code, 1, output)
        result = json.loads(output)
        self.assertFalse(result["ok"], result)
        self.assertEqual(result["state"], "blocked")
        self.assertEqual(result["lifecycle_action"], lifecycle_action)
        self.assertEqual(
            result["reason_codes"],
            ["compound_exact_human_approval_binding_required"],
        )
        self.assertFalse(result["private_values_echoed"])
        self.assertEqual(self.archive_tree_snapshot(archive_root), before)
        return result

    def zet_revision_state_for_bytes(self, value: bytes) -> dict[str, Any]:
        frontmatter, body = archive_services.split_zettel_text(
            archive_services.decode_utf8_with_universal_newlines(value)
        )
        frontmatter = archive_services.json_safe(frontmatter)
        first_read = archive_services.explicit_abstract_publication_check(
            frontmatter
        )
        self.assertTrue(first_read["ready_for_publication"], first_read)
        return {
            "file_sha256": "sha256:" + hashlib.sha256(value).hexdigest(),
            "semantic_sha256": archive_services.zet_revision_semantic_sha256(
                frontmatter, body
            ),
            "abstract_sha256": first_read["abstract_sha256"],
            "body_sha256": archive_services.canonical_body_sha256(
                archive_services.canonical_publication_body(body)
            ),
        }

    def rewrite_latest_revision_event_after_state(
        self,
        archive_root: Path,
        *,
        canonical_path: Path,
        target_bytes: bytes,
    ) -> Path:
        receipt_root = archive_root / "receipts" / "revisions" / "canonical"
        receipts = [
            (path, json.loads(path.read_text(encoding="utf-8")))
            for path in receipt_root.glob("*.zet-revision.json")
        ]
        receipt_path, receipt = max(
            receipts, key=lambda item: item[1]["revision_at"]
        )
        target_state = self.zet_revision_state_for_bytes(target_bytes)
        self.assertNotEqual(receipt["before"]["file_sha256"], target_state["file_sha256"])
        receipt["after"] = target_state
        receipt["abstract_review_basis"]["abstract_sha256"] = target_state[
            "abstract_sha256"
        ]
        receipt["abstract_review_basis"]["body_sha256"] = target_state[
            "body_sha256"
        ]
        receipt_path.write_text(
            json.dumps(receipt, indent=2, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
        canonical_path.write_bytes(target_bytes)
        return receipt_path

    def create_followup_zet_revision_proposal(
        self,
        archive_root: Path,
        canonical_path: Path,
        *,
        name: str,
        title_marker: str,
        abstract_marker: str,
        body_marker: str,
    ) -> dict[str, Any]:
        current_bytes = canonical_path.read_bytes()
        frontmatter, body = archive_services.split_zettel_text(
            canonical_path.read_text(encoding="utf-8")
        )
        proposed_frontmatter = json.loads(json.dumps(frontmatter))
        proposed_frontmatter["title"] = title_marker
        proposed_frontmatter["abstract"] = abstract_marker
        proposal_relative = f".wom-scratch/revisions/{name}"
        proposal_path = archive_root / proposal_relative
        proposal_path.parent.mkdir(parents=True, exist_ok=True)
        proposal_path.write_text(
            "---\n"
            + archive_cli.dump_yaml(proposed_frontmatter)
            + "---\n\n"
            + body.rstrip()
            + f"\n\n{body_marker}\n",
            encoding="utf-8",
        )
        plan = archive_services.zet_revision_plan(
            archive_root,
            zettel_id=frontmatter["id"],
            proposal_path=proposal_relative,
            dry_run=True,
        )
        self.assertTrue(plan["ok"], plan)
        return {
            "canonical_path": canonical_path,
            "original_bytes": current_bytes,
            "zettel_id": frontmatter["id"],
            "proposal_relative": proposal_relative,
            "proposal_path": proposal_path,
            "plan": plan,
            "title_marker": title_marker,
            "abstract_marker": abstract_marker,
            "body_marker": body_marker,
        }

