    def test_doctor_mint_receipt_file_sha_is_cached_per_run(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            mint = self._mint_lunch_for_reconcile(archive_root)
            receipt_path = archive_root / mint["mint_receipt_path"]
            receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
            target_path = archive_root / mint["canonical_path"]
            real_sha256_file = archive_cli.sha256_file
            sha_calls: list[Path] = []

            def counted_sha(path: Path, *args: Any, **kwargs: Any) -> str:
                sha_calls.append(path.resolve())
                return real_sha256_file(path)

            doctor = archive_cli.Doctor(archive_root)
            with patch.object(archive_cli, "sha256_file", side_effect=counted_sha):
                first = doctor._check_mint_receipt_file_ref(receipt, receipt_path, "target")
                second = doctor._check_mint_receipt_file_ref(receipt, receipt_path, "target")
                self.assertEqual(first.resolve() if first is not None else None, target_path.resolve())
                self.assertEqual(second.resolve() if second is not None else None, target_path.resolve())

        self.assertEqual(sha_calls.count(target_path.resolve()), 1)

    def test_doctor_mint_receipts_progress_reports_substeps_and_cache_summary(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            self._mint_lunch_for_reconcile(archive_root)
            events: list[tuple[str, str, int | None, int | None]] = []
            doctor = archive_cli.Doctor(
                archive_root,
                progress_callback=lambda stage, message, current, total: events.append(
                    (stage, message, current, total)
                ),
            )
            doctor._check_mint_receipts()

        messages = [message for stage, message, _current, _total in events if stage == "mint-receipts"]
        self.assertIn("loading receipt json", messages)
        self.assertIn("checking target file ref", messages)
        self.assertIn("target frontmatter reading text", messages)
        self.assertIn("target frontmatter loading yaml", messages)
        self.assertIn("reading target mint block", messages)
        self.assertIn("reading target mint receipt_path", messages)
        self.assertIn("comparing target mint receipt_path", messages)
        self.assertIn("target mint receipt link ok", messages)
        self.assertIn("completed receipt checks", messages)
        self.assertIn("resolving target file path", messages)
        self.assertIn("checking target file exists", messages)
        self.assertTrue(any(message.startswith("resolved target file ref ") for message in messages))
        self.assertIn("checking target sha256 field", messages)
        self.assertIn("reading target file stat", messages)
        self.assertIn("hashing target file bytes", messages)
        self.assertIn("hashed target file bytes", messages)
        self.assertIn("target file ref ok", messages)
        self.assertTrue(any(message.startswith("cache summary ") for message in messages))

    def test_doctor_mint_receipts_progress_reports_fourth_receipt_and_heartbeat(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            mint = self._mint_lunch_for_reconcile(archive_root)
            receipt_path = archive_root / mint["mint_receipt_path"]
            for index in range(2, 13):
                shutil.copy2(
                    receipt_path,
                    receipt_path.with_name(f"zet_20260519_draft_ai_lunch_note_copy_{index}.mint.json"),
                )
            events: list[tuple[str, str, int | None, int | None]] = []
            doctor = archive_cli.Doctor(
                archive_root,
                progress_callback=lambda stage, message, current, total: events.append(
                    (stage, message, current, total)
                ),
            )
            doctor._check_mint_receipts()

        mint_events = [(message, current, total) for stage, message, current, total in events if stage == "mint-receipts"]
        self.assertTrue(any(current == 4 and total == 12 for _message, current, total in mint_events))
        self.assertTrue(any(current == 9 and total == 12 for _message, current, total in mint_events))
        self.assertIn(("started receipt checks", 9, 12), mint_events)
        self.assertIn(("checking target file ref", 9, 12), mint_events)
        self.assertIn(("resolving target file path", 9, 12), mint_events)
        self.assertIn(("checking target file exists", 9, 12), mint_events)
        self.assertTrue(
            any(
                message.startswith("resolved target file ref ") and current == 9 and total == 12
                for message, current, total in mint_events
            )
        )
        self.assertIn(("checking target sha256 field", 9, 12), mint_events)
        self.assertTrue(
            ("reading target file stat", 9, 12) in mint_events
            or ("target file sha256 cache hit", 9, 12) in mint_events
        )
        self.assertTrue(
            ("hashing target file bytes", 9, 12) in mint_events
            or ("target file sha256 cache hit", 9, 12) in mint_events
        )
        self.assertTrue(
            ("hashed target file bytes", 9, 12) in mint_events
            or ("target file sha256 cache hit", 9, 12) in mint_events
        )
        self.assertIn(("target file ref ok", 9, 12), mint_events)
        self.assertIn(("completed receipt checks", 9, 12), mint_events)
        self.assertIn(
            (
                "continuing with receipt heartbeat; minimal file-ref liveness every receipt; detailed substeps every 250 receipts",
                4,
                12,
            ),
            mint_events,
        )

    def test_doctor_mint_receipt_file_ref_passes_hash_progress_callback(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            mint = self._mint_lunch_for_reconcile(archive_root)
            receipt_path = archive_root / mint["mint_receipt_path"]
