    def test_project_update_snapshot_rejects_noncanonical_nul_records(
        self,
    ) -> None:
        if shutil.which("git") is None:
            self.skipTest("git is required for the snapshot regression")
        with tempfile.TemporaryDirectory() as tmp:
            repository = Path(tmp) / "repository"
            repository.mkdir()
            self.git_fixture_command(repository, "init", "-b", "main")
            self.git_fixture_command(
                repository,
                "config",
                "user.name",
                "archive-test",
            )
            self.git_fixture_command(
                repository,
                "config",
                "user.email",
                "archive-test.invalid",
            )
            (repository / "tracked.txt").write_text(
                "tracked\n",
                encoding="utf-8",
            )
            self.git_fixture_command(repository, "add", "tracked.txt")
            self.git_fixture_command(
                repository,
                "commit",
                "-m",
                "NUL record fixture",
            )
            (repository / "untracked.txt").write_text(
                "untracked\n",
                encoding="utf-8",
            )
            real_git = archive_services._wom_kit_project_update_git
            nul_commands = (
                ("ls-tree", "-r", "-z", "HEAD"),
                ("ls-files", "--stage", "-z"),
                ("ls-files", "-v", "-z"),
                ("ls-files", "--eol", "-z"),
                (
                    "ls-files",
                    "--others",
                    "--exclude-standard",
                    "-z",
                ),
            )
            for target_args in nul_commands:
                for corruption in ("missing_terminator", "empty_record"):
                    with self.subTest(
                        command=target_args,
                        corruption=corruption,
                    ):

                        def corrupt_git_output(
                            mirror_path: Path,
                            args: list[str],
                            **kwargs: Any,
                        ) -> tuple[bool, str]:
                            ok, value = real_git(
                                mirror_path,
                                args,
                                **kwargs,
                            )
                            if tuple(args) != target_args or not ok:
                                return ok, value
                            self.assertTrue(value.endswith("\0"))
                            if corruption == "missing_terminator":
                                return True, value[:-1]
                            return True, value + "\0"

                        with patch.object(
                            archive_services,
                            "_wom_kit_project_update_git",
                            side_effect=corrupt_git_output,
                        ):
                            self.assertIsNone(
                                archive_services
                                ._wom_kit_project_update_git_snapshot(
                                    repository
                                )
                            )

            for corruption in ("unknown_token", "control_whitespace"):
                with self.subTest(
                    command=("ls-files", "--eol", "-z"),
                    corruption=corruption,
                ):

                    def corrupt_eol_output(
                        mirror_path: Path,
                        args: list[str],
                        **kwargs: Any,
                    ) -> tuple[bool, str]:
                        ok, value = real_git(
                            mirror_path,
                            args,
                            **kwargs,
                        )
                        if tuple(args) != (
                            "ls-files",
                            "--eol",
                            "-z",
                        ) or not ok:
                            return ok, value
                        if corruption == "unknown_token":
                            return True, re.sub(
                                r"^i/\S+",
                                "i/unknown",
                                value,
                                count=1,
                            )
                        return True, re.sub(
                            r"^(i/\S+)[ ]+(w/\S+)",
                            "\\1\v\\2",
                            value,
                            count=1,
                        )

                    with patch.object(
                        archive_services,
                        "_wom_kit_project_update_git",
                        side_effect=corrupt_eol_output,
                    ):
                        self.assertIsNone(
                            archive_services
                            ._wom_kit_project_update_git_snapshot(
                                repository
                            )
                        )

    def test_project_update_lock_rejects_reparse_and_identity_replacement(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            project_root = Path(tmp) / "project"
            metadata_root = project_root / ".zettel-kasten"
            metadata_root.mkdir(parents=True)
            lock_path = metadata_root / "version-update.lock"
            captured_identity: list[tuple[int, int]] = []
            identity = (
                archive_services
                ._wom_kit_project_update_acquire_lock_exclusive(
                    project_root,
                    metadata_root,
                    lock_path,
                    reservation_callback=captured_identity.append,
                )
            )
            self.assertEqual(captured_identity, [identity])
            replacement_path = lock_path.with_name(
                "version-update-replacement.lock"
            )
            replacement_path.write_bytes(
                archive_services.WOM_KIT_PROJECT_UPDATE_LOCK_BYTES
            )
            replacement_stat = os.lstat(replacement_path)
            replacement_identity = (
                replacement_stat.st_dev,
                replacement_stat.st_ino,
            )
            self.assertNotEqual(replacement_identity, identity)
            os.replace(replacement_path, lock_path)
            self.assertFalse(
                archive_services.wom_kit_project_update_owned_lock_present(
                    project_root,
                    lock_path,
                    identity,
                )
            )
            self.assertFalse(
                archive_services._wom_kit_project_update_release_owned_lock(
                    project_root,
                    lock_path,
                    identity,
                )
            )
            self.assertEqual(
                lock_path.read_bytes(),
                archive_services.WOM_KIT_PROJECT_UPDATE_LOCK_BYTES,
            )
            lock_path.unlink()

            external_lock = Path(tmp) / "external-lock"
            external_bytes = b"EXTERNAL_LOCK_MUST_NOT_BE_TOUCHED\n"
            external_lock.write_bytes(external_bytes)
            try:
                lock_path.symlink_to(external_lock)
            except OSError:
                return
            with self.assertRaises(OSError):
                archive_services._wom_kit_project_update_acquire_lock_exclusive(
                    project_root,
                    metadata_root,
                    lock_path,
                    reservation_callback=lambda _identity: None,
                )
            self.assertEqual(external_lock.read_bytes(), external_bytes)

    def test_project_update_lock_and_receipt_reject_parent_reparse_swap_before_reservation(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            tmp_root = Path(tmp)
            project_root = tmp_root / "project"
            metadata_root = project_root / ".zettel-kasten"
            metadata_root.mkdir(parents=True)
            external_metadata = tmp_root / "external-metadata"
            external_metadata.mkdir()
            lock_path = metadata_root / "version-update.lock"
            lock_reservations: list[tuple[int, int]] = []
            real_open = os.open
            metadata_backup = project_root / ".zettel-kasten-real"
            swapped_lock_parent = False

            def swap_lock_parent_then_open(
                path: str | bytes | os.PathLike[str] | os.PathLike[bytes],
                flags: int,
                mode: int = 0o777,
            ) -> int:
                nonlocal swapped_lock_parent
                candidate = Path(path)
                if candidate == lock_path and not swapped_lock_parent:
                    metadata_root.rename(metadata_backup)
                    try:
                        metadata_root.symlink_to(
                            external_metadata,
                            target_is_directory=True,
                        )
                    except OSError:
                        metadata_backup.rename(metadata_root)
                        raise
                    swapped_lock_parent = True
                return real_open(path, flags, mode)

            try:
                with patch.object(
                    archive_services.os,
                    "open",
                    side_effect=swap_lock_parent_then_open,
                ):
                    with self.assertRaises(OSError):
                        (
                            archive_services
                            ._wom_kit_project_update_acquire_lock_exclusive(
                                project_root,
                                metadata_root,
                                lock_path,
                                reservation_callback=(
                                    lock_reservations.append
                                ),
                            )
                        )
            except OSError as exc:
                if not swapped_lock_parent:
                    self.skipTest(
                        f"directory symlinks are unavailable: {exc}"
                    )
                raise
            self.assertEqual(lock_reservations, [])
            self.assertEqual(list(external_metadata.iterdir()), [])

        with tempfile.TemporaryDirectory() as tmp:
            tmp_root = Path(tmp)
            project_root = tmp_root / "project"
            project_root.mkdir()
            receipts_root = (
                project_root
                / ".zettel-kasten"
                / "receipts"
                / "version-updates"
            )
            receipts_root.mkdir(parents=True)
            external_receipts = tmp_root / "external-receipts"
            external_receipts.mkdir()
            receipts_backup = receipts_root.with_name(
                "version-updates-real"
            )
            receipt_reservations: list[
                tuple[Path, str, tuple[int, int]]
            ] = []
            real_open = os.open
            swapped_receipt_parent = False
            receipt_parent_rename_blocked = False
            directory_guard = (
                archive_services._WomKitProjectUpdateDirectoryGuard(
                    project_root
                )
            )
            self.assertTrue(
                directory_guard.hold_existing_tree(project_root)
            )

            def swap_receipt_parent_then_open(
                path: str | bytes | os.PathLike[str] | os.PathLike[bytes],
                flags: int,
                mode: int = 0o777,
            ) -> int:
                nonlocal swapped_receipt_parent
                nonlocal receipt_parent_rename_blocked
                candidate = Path(path)
                if (
                    candidate.parent == receipts_root
                    and not swapped_receipt_parent
                ):
                    try:
                        receipts_root.rename(receipts_backup)
                    except OSError:
                        receipt_parent_rename_blocked = True
                        raise
                    try:
                        receipts_root.symlink_to(
                            external_receipts,
                            target_is_directory=True,
                        )
                    except OSError:
                        receipts_backup.rename(receipts_root)
                        raise
                    swapped_receipt_parent = True
                return real_open(path, flags, mode)

            try:
                try:
                    with patch.object(
                        archive_services.os,
                        "open",
                        side_effect=swap_receipt_parent_then_open,
                    ):
                        with self.assertRaises(OSError):
                            (
                                archive_services
                                ._wom_kit_project_update_write_receipt_exclusive(
                                    project_root,
                                    "v0.3.291",
                                    "2026-07-30T12:34:56Z",
                                    b'{"receipt":"parent-swap"}\n',
                                    directory_guard=directory_guard,
                                    reservation_callback=(
                                        lambda path, relative, identity: (
                                            receipt_reservations.append(
                                                (
                                                    path,
                                                    relative,
                                                    identity,
                                                )
                                            )
                                        )
                                    ),
                                )
                            )
                except OSError as exc:
                    if (
                        not swapped_receipt_parent
                        and not receipt_parent_rename_blocked
                    ):
                        self.skipTest(
                            f"directory symlinks are unavailable: {exc}"
                        )
                    raise
            finally:
                directory_guard.close()
            self.assertEqual(receipt_reservations, [])
            self.assertEqual(list(external_receipts.iterdir()), [])

    def test_project_update_receipt_reservation_keyboard_interrupt_cleans_owned_file(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            project_root = Path(tmp) / "project"
            receipts_root = (
                project_root
                / ".zettel-kasten"
                / "receipts"
                / "version-updates"
            )
            receipts_root.mkdir(parents=True)
            reservations: list[tuple[Path, str, tuple[int, int]]] = []
            directory_guard = (
                archive_services._WomKitProjectUpdateDirectoryGuard(
                    project_root
                )
            )
            self.assertTrue(directory_guard.hold(receipts_root))

            def interrupt_after_reservation(
                path: Path,
                relative: str,
                identity: tuple[int, int],
            ) -> None:
                reservations.append((path, relative, identity))
                raise KeyboardInterrupt()

            try:
                with self.assertRaises(KeyboardInterrupt):
                    (
                        archive_services
                        ._wom_kit_project_update_write_receipt_exclusive(
                            project_root,
                            "v0.3.291",
                            "2026-07-30T12:34:56Z",
                            b'{"receipt":"must-not-survive"}\n',
                            directory_guard=directory_guard,
                            reservation_callback=(
                                interrupt_after_reservation
                            ),
                        )
                    )
            finally:
                directory_guard.close()
            self.assertEqual(len(reservations), 1)
            self.assertFalse(reservations[0][0].exists())
            self.assertEqual(
                list(receipts_root.iterdir()) if receipts_root.exists() else [],
                [],
            )

