    def test_credential_adopt_binds_stable_request_and_never_accepts_or_echoes_pat(self) -> None:
        help_code, help_output = self.run_cli(["credential-adopt", "--help"])
        self.assertEqual(help_code, 0, help_output)
        self.assertIn("--task-summary", help_output)
        self.assertIn("--connection-reason", help_output)
        self.assertIn("--replace-existing", help_output)
        self.assertIn("First-time enrollment", help_output)
        normalized_help = " ".join(help_output.split())
        self.assertIn("separate native Windows popup", normalized_help)
        self.assertIn("actual credential registration", normalized_help)
        self.assertIn("synthetic acceptance harness", normalized_help)
        self.assertNotIn("attached Windows terminal", help_output)
        self.assertNotIn("No separate window", help_output)
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            anchor = "00000000-0000-0000-0000-000000000071"
            account_label = "private account label"
            workspace_label = "private workspace label"
            task_summary = "검토한 Notion 페이지를 WOM 아카이브로 복구하고 있습니다."
            connection_reason = "복구를 계속하려면 해당 Notion 작업공간 연결을 확인해야 합니다."
            token = "secret-token-value-that-must-never-echo"
            base = [
                "credential-adopt",
                str(archive_root),
                "--account-label",
                account_label,
                "--workspace-label",
                workspace_label,
                "--purpose",
                "notion-page-recovery",
                "--task-summary",
                task_summary,
                "--connection-reason",
                connection_reason,
                "--reviewed-anchor-page-id",
                anchor,
                "--capability",
                "read-page-content",
                "--interactive",
                "--format",
                "json",
            ]
            before = self.snapshot_archive_files(archive_root)

            first_code, first_output = self.run_cli([*base, "--dry-run"])
            second_code, second_output = self.run_cli([*base, "--dry-run"])
            first = json.loads(first_output)
            second = json.loads(second_output)
            self.assertEqual(first_code, 0, first_output)
            self.assertEqual(second_code, 0, second_output)
            self.assertEqual(first["request_sha256"], second["request_sha256"])
            self.assertRegex(first["request_sha256"], r"^sha256:[0-9a-f]{64}$")
            interaction_context = {
                "schema": "wom-credential-interaction-context/v0.1",
                "provider": "notion",
                "purpose": "notion_page_recovery",
                "account_label": account_label,
                "workspace_label": workspace_label,
                "task_summary": task_summary,
                "connection_reason": connection_reason,
            }
            expected_interaction_context_sha256 = "sha256:" + hashlib.sha256(
                json.dumps(
                    interaction_context,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            self.assertEqual(
                first["interaction_context_sha256"],
                expected_interaction_context_sha256,
            )
            canonical_request = {
                "schema": "wom-kit/credential-adoption-request/v0.2",
                "archive_id": "archive:personal:fake-life",
                "provider": "notion",
                "account_label": account_label,
                "workspace_label": workspace_label,
                "purpose": "notion_page_recovery",
                "task_summary": task_summary,
                "connection_reason": connection_reason,
                "interaction_context_sha256": expected_interaction_context_sha256,
                "replace_existing": False,
                "reviewed_anchor_page_id": anchor,
                "requested_capabilities": ["read_page_content"],
                "ttl_seconds": 300,
                "interactive": True,
            }
            expected_request_sha256 = "sha256:" + hashlib.sha256(
                json.dumps(
                    canonical_request,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                ).encode("utf-8")
            ).hexdigest()
            self.assertEqual(first["request_sha256"], expected_request_sha256)
            self.assertNotIn("plan_digest", first)
            self.assertNotIn("intake_plan", first)
            self.assertTrue(first["assistant_task_context_bound"])
            for private_value in (anchor, account_label, workspace_label):
                self.assertNotIn(private_value, first_output)
            self.assertEqual(before, self.snapshot_archive_files(archive_root))

            replacement_code, replacement_output = self.run_cli(
                [*base, "--replace-existing", "--dry-run"]
            )
            replacement = json.loads(replacement_output)
            self.assertEqual(replacement_code, 0, replacement_output)
            self.assertNotEqual(
                replacement["request_sha256"],
                first["request_sha256"],
            )
            self.assertEqual(
                replacement["interaction_context_sha256"],
                first["interaction_context_sha256"],
            )

            with patch(
                "wom_kit.credential_workflows.execute_windows_notion_credential_adoption"
            ) as execute:
                mismatch_code, mismatch_output = self.run_cli(
                    [
                        *base,
                        "--approve",
                        "--expected-request-sha256",
                        "sha256:" + "f" * 64,
                    ]
                )
            self.assertEqual(mismatch_code, 1, mismatch_output)
            self.assertFalse(execute.called)
            self.assertEqual(
                json.loads(mismatch_output)["reason_code"],
                "credential_adoption_request_sha256_mismatch",
            )

            safe_worker_result = {
                "schema_version": "wom-credential-workflow-result/v0.3",
                "ok": True,
                "lifecycle_action": "secure_credential_adoption_execute",
                "accepted": True,
                "persisted": True,
                "reason_code": "credential_adoption_persisted_and_rediscoverable",
                "credential_id": "cred_1234567890abcdef",
                "authenticated_rediscovery_verified": True,
                "human_default_decision_required": True,
                "secret_value_present": False,
                "reviewed_anchor_present_in_result": False,
                "backend_target_present": False,
                "crash_or_power_loss_rollback_guaranteed": False,
                "credential_input_received": True,
                "complete_line_received": True,
                "temporary_store_write_attempted": True,
                "provider_request_attempted": True,
            }
            with patch(
                "wom_kit.credential_workflows.execute_windows_notion_credential_adoption",
                return_value=safe_worker_result,
            ) as execute:
                approve_code, approve_output = self.run_cli(
                    [
                        *base,
                        "--approve",
                        "--expected-request-sha256",
                        first["request_sha256"],
                    ]
                )
            approved = json.loads(approve_output)
            self.assertEqual(approve_code, 0, approve_output)
            self.assertTrue(approved["persisted"])
            self.assertTrue(approved["credential_input_received"])
            self.assertTrue(approved["complete_line_received"])
            self.assertTrue(approved["temporary_store_write_attempted"])
            self.assertTrue(approved["provider_request_attempted"])
            self.assertEqual(approved["request_sha256"], first["request_sha256"])
            self.assertNotIn("plan_digest", approved)
            self.assertTrue(execute.call_args.kwargs["approved"])
            self.assertEqual(
                execute.call_args.kwargs["expected_plan_digest"],
                execute.call_args.args[1]["plan_digest"],
            )
            self.assertEqual(
                execute.call_args.kwargs["reviewed_anchor_uuid"], anchor
            )
            for private_value in (anchor, account_label, workspace_label):
                self.assertNotIn(private_value, approve_output)
            self.assertEqual(before, self.snapshot_archive_files(archive_root))

            legacy_worker_result = dict(safe_worker_result)
            legacy_worker_result["schema_version"] = (
                "wom-credential-workflow-result/v0.2"
            )
            for stage_field in (
                "credential_input_received",
                "complete_line_received",
                "temporary_store_write_attempted",
                "provider_request_attempted",
            ):
                legacy_worker_result.pop(stage_field)
            with patch(
                "wom_kit.credential_workflows.execute_windows_notion_credential_adoption",
                return_value=legacy_worker_result,
            ):
                legacy_code, legacy_output = self.run_cli(
                    [
                        *base,
                        "--approve",
                        "--expected-request-sha256",
                        first["request_sha256"],
                    ]
                )
            legacy = json.loads(legacy_output)
            self.assertEqual(legacy_code, 1, legacy_output)
            self.assertEqual(
                legacy["reason_code"], "credential_adoption_worker_state_unknown"
            )
            for stage_field in (
                "credential_input_received",
                "complete_line_received",
                "temporary_store_write_attempted",
                "provider_request_attempted",
            ):
                self.assertIsNone(legacy[stage_field])

            from wom_kit import credential_workflows

            for reason_code, rollback_status, stage_evidence in (
                (
                    "credential_input_cancelled_or_empty",
                    "not_required",
                    (True, True, False, False),
                ),
                (
                    "credential_input_not_received",
                    "not_required",
                    (False, False, False, False),
                ),
                (
                    "credential_input_invalid_for_provider",
                    "not_required",
                    (True, True, False, False),
                ),
                (
                    "credential_input_boundary_failed",
                    "not_required",
                    (True, True, False, False),
                ),
                (
                    "provider_request_not_attempted",
                    "deleted",
                    (True, True, True, False),
                ),
                (
                    "provider_auth_rejected",
                    "deleted",
                    (True, True, True, True),
                ),
                (
                    "provider_identity_endpoint_unavailable",
                    "deleted",
                    (True, True, True, True),
                ),
                (
                    "reviewed_anchor_inaccessible",
                    "deleted",
                    (True, True, True, True),
                ),
            ):
                with self.subTest(reason_code=reason_code), patch(
                    "wom_kit.credential_workflows.execute_windows_notion_credential_adoption",
                    return_value=credential_workflows._approved_adoption_worker_failure(
                        reason_code,
                        rollback_status=rollback_status,
                        credential_input_received=stage_evidence[0],
                        complete_line_received=stage_evidence[1],
                        temporary_store_write_attempted=stage_evidence[2],
                        provider_request_attempted=stage_evidence[3],
                    ),
                ):
                    failure_code, failure_output = self.run_cli(
                        [
                            *base,
                            "--approve",
                            "--expected-request-sha256",
                            first["request_sha256"],
                        ]
                    )
                failure = json.loads(failure_output)
                self.assertEqual(failure_code, 1, failure_output)
                self.assertEqual(
                    failure["schema_version"],
                    "wom-credential-workflow-result/v0.3",
                )
                self.assertFalse(failure["accepted"])
                self.assertFalse(failure["persisted"])
                self.assertEqual(failure["reason_code"], reason_code)
                self.assertEqual(failure["rollback_status"], rollback_status)
                self.assertEqual(
                    failure["store_absence_verified"],
                    rollback_status == "deleted",
                )
                self.assertFalse(failure["secret_value_present"])
                self.assertEqual(
                    tuple(
                        failure[field]
                        for field in (
                            "credential_input_received",
                            "complete_line_received",
                            "temporary_store_write_attempted",
                            "provider_request_attempted",
                        )
                    ),
                    stage_evidence,
                )
                for private_value in (
                    anchor,
                    account_label,
                    workspace_label,
                    token,
                ):
                    self.assertNotIn(private_value, failure_output)

            with patch(
                "wom_kit.credential_workflows.execute_windows_notion_credential_adoption",
                return_value=credential_workflows._uncertain_adoption_worker_result(),
            ):
                unknown_code, unknown_output = self.run_cli(
                    [
                        *base,
                        "--approve",
                        "--expected-request-sha256",
                        first["request_sha256"],
                    ]
                )
            unknown = json.loads(unknown_output)
            self.assertEqual(unknown_code, 1, unknown_output)
            self.assertEqual(
                unknown["reason_code"], "credential_adoption_worker_state_unknown"
            )
            for stage_field in (
                "credential_input_received",
                "complete_line_received",
                "temporary_store_write_attempted",
                "provider_request_attempted",
            ):
                self.assertIsNone(unknown[stage_field])

            forbidden_code, forbidden_output = self.run_cli(
                [*base, "--approve", "--token", token]
            )
            self.assertEqual(forbidden_code, 2, forbidden_output)
            self.assertEqual(
                json.loads(forbidden_output)["reason_codes"],
                ["credential_secret_input_option_forbidden"],
            )
            self.assertNotIn(token, forbidden_output)

            token_shaped_label = "ntn_" + "A" * 32
            label_code, label_output = self.run_cli(
                [
                    "credential-adopt",
                    str(archive_root),
                    "--account-label",
                    token_shaped_label,
                    "--workspace-label",
                    workspace_label,
                    "--task-summary",
                    task_summary,
                    "--connection-reason",
                    connection_reason,
                    "--reviewed-anchor-page-id",
                    anchor,
                    "--interactive",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(label_code, 1, label_output)
            self.assertEqual(
                json.loads(label_output)["reason_code"],
                "credential_adoption_request_invalid",
            )
            self.assertNotIn(token_shaped_label, label_output)

