    def test_zettel_edge_batch_plan_path_is_archive_relative_first(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            plan_path = archive_root / "workbench" / "zettel-edge-batch-relative.plan.json"
            plan = {
                "schema": "wom-kit/zettel-edge-batch/v0.1",
                "policy": {
                    "policy_id": "policy:fixture-relative-plan",
                    "auto_write_edge_types": ["material"],
                    "minimum_confidence": "high",
                },
                "edges": [
                    {
                        "candidate_id": "candidate:fixture-relative-plan-material",
                        "from_zettel": "zet_20240504_fake_lunch_thought",
                        "target": "zet_20240505_fake_company_onboarding_insight",
                        "edge_type": "material",
                        "visibility": "private",
                        "confidence": "high",
                        "review_status": "policy_candidate",
                    }
                ],
            }
            plan_path.write_text(json.dumps(plan, indent=2), encoding="utf-8")
            before = self.snapshot_archive_files(archive_root)

            code, output = self.run_cli(
                [
                    "zettel-edge-batch",
                    str(archive_root),
                    "--plan",
                    "workbench/zettel-edge-batch-relative.plan.json",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            result = json.loads(output)
            serialized = json.dumps(result, ensure_ascii=False)
            self.assertEqual(code, 0, output)
            self.assertTrue(result["ok"])
            self.assertEqual(result["plan_path_resolution"]["resolved_as"], "archive_relative")
            self.assertEqual(result["plan_path_resolution"]["archive_relative_path"], "workbench/zettel-edge-batch-relative.plan.json")
            self.assertNotIn(str(archive_root.resolve()), serialized)
            self.assertEqual(self.snapshot_archive_files(archive_root), before)

            missing_code, missing_output = self.run_cli(
                [
                    "zettel-edge-batch",
                    str(archive_root),
                    "--plan",
                    "workbench/missing-zettel-edge-batch.plan.json",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            missing = json.loads(missing_output)
            self.assertEqual(missing_code, 1)
            self.assertIn("archive-relative first", "\n".join(missing["blockers"]))
            self.assertNotIn(str(archive_root.resolve()), missing_output)

    def test_imap_mailbox_plan_is_read_only_and_blocks_secret_values(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            before = self.snapshot_archive_files(archive_root)

            code, output = self.run_cli(
                [
                    "imap-mailbox-plan",
                    str(archive_root),
                    "--source-id",
                    "imap:gmail",
                    "--provider",
                    "gmail",
                    "--account-ref",
                    "imap:account:gmail-personal",
                    "--username-ref",
                    "env:WOM_GMAIL_USERNAME",
                    "--auth-mode",
                    "oauth_token_ref",
                    "--oauth-token-ref",
                    "keyring:gmail-oauth",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )

            result = json.loads(output)
            self.assertEqual(code, 0, output)
            self.assertTrue(result["ok"])
            self.assertEqual(result["lifecycle_action"], "imap_mailbox_plan")
            self.assertEqual(result["source_type"], "imap_mailbox")
            self.assertEqual(result["server"]["imap_host"], "imap.gmail.com")
            self.assertEqual(result["server"]["imap_port"], 993)
            self.assertFalse(result["current_capability"]["live_imap_scan_implemented"])
            self.assertFalse(result["closed_actions"]["imap_connection_opened"])
            self.assertFalse(result["closed_actions"]["message_headers_read"])
            self.assertFalse(result["privacy_guards"]["email_addresses_echoed"])
            self.assertFalse(result["privacy_guards"]["credential_values_echoed"])
            self.assertEqual(result["would_change"], [])
            self.assertEqual(self.snapshot_archive_files(archive_root), before)

            bad_code, bad_output = self.run_cli(
                [
                    "imap-mailbox-plan",
                    str(archive_root),
                    "--source-id",
                    "imap:gmail",
                    "--provider",
                    "gmail",
                    "--account-ref",
                    "imap:account:gmail-personal",
                    "--username-ref",
                    "person@example.com",
                    "--app-password-ref",
                    "abcdabcdabcdabcd",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )

            bad_result = json.loads(bad_output)
            self.assertEqual(bad_code, 1, bad_output)
            self.assertFalse(bad_result["ok"])
            self.assertTrue(any("username_ref" in blocker for blocker in bad_result["blockers"]))
            self.assertTrue(any("app_password_ref" in blocker for blocker in bad_result["blockers"]))
            self.assertNotIn("person@example.com", bad_output)
            self.assertNotIn("abcdabcdabcdabcd", bad_output)
            self.assertEqual(self.snapshot_archive_files(archive_root), before)

            wrong_account_code, wrong_account_output = self.run_cli(
                [
                    "imap-mailbox-plan",
                    str(archive_root),
                    "--source-id",
                    "imap:naver",
                    "--provider",
                    "naver",
                    "--account-ref",
                    "keyring:naver-account",
                    "--username-ref",
                    "env:NAVER_IMAP_USERNAME",
                    "--app-password-ref",
                    "keyring:naver-app-password",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            wrong_account = json.loads(wrong_account_output)
            self.assertEqual(wrong_account_code, 1, wrong_account_output)
            self.assertFalse(wrong_account["ok"])
            self.assertTrue(any("account_ref is a non-secret account label" in blocker for blocker in wrong_account["blockers"]))
            self.assertIsNone(wrong_account["auth"]["account_ref"])
            self.assertNotIn("keyring:naver-account", wrong_account_output)

