    _BASOON_PREFIX = "archives/archive:personal:basoon/objets"

    def _adopt_env(self):
        return patch.dict(
            archive_services.os.environ,
            {"WOM_R2_ACCESS_KEY_ID": _R2_ACCESS_KEY_ID, "WOM_R2_SECRET_ACCESS_KEY": _R2_SECRET_HEX64},
            clear=False,
        )

    def _adopt_run(self, root, **kwargs):
        defaults = dict(
            provider_kind="cloudflare-r2",
            store_ref="r2-basoon-20260704",
            access_key_id_ref="env:WOM_R2_ACCESS_KEY_ID",
            secret_access_key_ref="env:WOM_R2_SECRET_ACCESS_KEY",
        )
        defaults.update(kwargs)
        return archive_services.object_storage_adopt_existing_run(root, **defaults)

    def assert_object_storage_upload_fails_closed(
        self,
        archive_root: Path,
        **overrides: Any,
    ) -> dict[str, Any]:
        arguments: dict[str, Any] = {
            "approve": True,
            "reviewed_by": "person:object-storage-upload-fixed-gate-reviewer",
        }
        arguments.update(overrides)
        before = self.archive_tree_snapshot(archive_root)
        result = self._upload_run(archive_root, **arguments)
        self.assert_compound_revision_write_blocked(
            result,
            lifecycle_action="object_storage_upload_run",
        )
        self.assertEqual(self.archive_tree_snapshot(archive_root), before)
        return result

    def assert_object_storage_adopt_fails_closed(
        self,
        archive_root: Path,
        **overrides: Any,
    ) -> dict[str, Any]:
        arguments: dict[str, Any] = {
            "approve": True,
            "reviewed_by": "person:object-storage-adopt-fixed-gate-reviewer",
        }
        arguments.update(overrides)
        before = self.archive_tree_snapshot(archive_root)
        result = self._adopt_run(archive_root, **arguments)
        self.assert_compound_revision_write_blocked(
            result,
            lifecycle_action="object_storage_adopt_existing",
        )
        self.assertEqual(self.archive_tree_snapshot(archive_root), before)
        return result

    def assert_object_storage_setup_fails_closed(
        self,
        archive_root: Path,
    ) -> dict[str, Any]:
        before = self.archive_tree_snapshot(archive_root)
        code, output = self.run_cli(
            [
                "object-storage",
                str(archive_root),
                "--approve",
                "--reviewed-by",
                "person:object-storage-setup-fixed-gate-reviewer",
                "--write-local-profile",
                "--provider",
                "cloudflare-r2",
                "--profile-id",
                "profile:personal:fixed-gate",
                "--profile-slug",
                "fixed-gate",
                "--storage-account-ref",
                "storage:account:fixed-gate",
                "--format",
                "json",
            ]
        )
        self.assertEqual(code, 1, output)
        result = json.loads(output)
        self.assertEqual(result["state"], "blocked")
        self.assertEqual(result["lifecycle_action"], "object_storage_setup")
        self.assertEqual(
            result["reason_codes"],
            ["compound_exact_human_approval_binding_required"],
        )
        self.assertFalse(result["private_values_echoed"])
        self.assertEqual(self.archive_tree_snapshot(archive_root), before)
        return result

