    def install_historical_restore_drill_fixture(
        self,
        archive_root: Path,
        target: Path,
        *,
        copy_target: bool,
    ) -> dict[str, Any]:
        """Install bounded pre-v0.4 restore evidence without calling its writer."""

        root = archive_root.resolve()
        target = target.resolve()
        self.assertFalse(target.exists())
        self.assertFalse(target.is_relative_to(root))
        self.assertFalse(root.is_relative_to(target))
        plan = archive_services.restore_drill_dry_run(root, target)
        self.assertTrue(plan["ok"], plan)

        changed_archive_paths: list[str] = []
        index_result: dict[str, Any] = {"status": "historical_fixture_only"}
        search_result: dict[str, Any] = {"query": "archive", "count": 0}
        if copy_target:
            target.mkdir(parents=True)
            for source in archive_services.iter_restore_drill_files(root):
                relative = archive_services.archive_relative_path(source, root)
                if archive_services.restore_drill_should_exclude(relative):
                    continue
                destination = target / Path(relative)
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, destination)
                changed_archive_paths.append(relative)
            index_result = archive_services.index_archive(target)
            search_result = archive_services.search_archive(target, "archive", limit=3)

        reviewed_at = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        timestamp_slug = time.strftime("%Y%m%dT%H%M%SZ", time.gmtime())
        receipt_relative = (
            f"{archive_services.RESTORE_DRILL_RECEIPTS_DIR}/"
            f"{timestamp_slug}.historical.restore-drill.json"
        )
        receipt = dict(plan["receipt_preview"])
        receipt.update(
            {
                "receipt_id": (
                    "receipt:restore-drill:"
                    f"{archive_services.safe_slug(plan['archive_id'])}:historical-{timestamp_slug}"
                ),
                "dry_run": False,
                "timestamp": reviewed_at,
                "reviewed_by": "person:historical-restore-reviewer",
                "reviewed_at": reviewed_at,
                "validation": {
                    "doctor_strict": {
                        "ok": True,
                        "errors": 0,
                        "warnings": 0,
                        "diagnostics": [],
                    },
                    "index": index_result,
                    "search_smoke": {
                        "ok": True,
                        "query": search_result["query"],
                        "count": search_result["count"],
                    },
                },
                "result": {
                    "status": "passed",
                    "changed_paths": [str(target), receipt_relative],
                    "restored_archive_file_count": len(changed_archive_paths),
                },
                "blockers": [],
                "warnings": [],
            }
        )
        self.assertEqual(
            archive_cli.validate_schema(receipt, "restore-drill-receipt.schema.json"),
            [],
        )
        receipt_path = archive_root / Path(receipt_relative)
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        receipt_path.write_text(
            json.dumps(receipt, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        return {
            "receipt": receipt,
            "receipt_path": receipt_relative,
            "target": target,
        }

