    # --- Stage 2: real transport via injected fake sender ---

    def test_s3_transport_put_head_roundtrip_via_fake_sender(self) -> None:
        s = archive_services
        # head_object verifies the whole-object sha256 by HeadObject (presence +
        # Content-Length) followed by GetObject-and-rehash (CB-Q2), NOT by any
        # stored server-side checksum. R2 does not implement GetObjectAttributes
        # and marks x-amz-checksum-sha256 "Feature Not Implemented".
        object_body = b"abc"
        digest = hashlib.sha256(object_body).hexdigest()
        calls = []

        def fake_send(*, method, url, headers, data_path=None, data_bytes=None):
            calls.append((method, dict(headers), url))
            if method == "PUT":
                return {"status": 200, "headers": {"etag": '"e"'}, "body": b""}
            if method == "HEAD":  # HeadObject: presence + size only
                return {"status": 200, "headers": {"content-length": str(len(object_body))}, "body": b""}
            if method == "GET":  # GetObject: real bytes, hashed to the whole-object sha256
                return {"status": 200, "headers": {}, "body": object_body}
            return {"status": 200, "headers": {}, "body": b""}

        cred = {
            "endpoint_host": "acct.r2.cloudflarestorage.com", "bucket": "mybucket",
            "access_key_id": "AKIAEX", "secret_access_key": "s" * 40, "region": "auto",
        }
        t = s._object_storage_resolve_transport("cloudflare-r2", send=fake_send, credential=cred)
        put = t.put_object(key="sha256/bb/" + digest, data_path=None, size=len(object_body), content_sha256=digest)
        self.assertEqual(put["status_class"], "ok")
        head = t.head_object(key="sha256/bb/" + digest)
        self.assertTrue(head["present"])
        self.assertEqual(head["size"], len(object_body))
        self.assertEqual(head["checksum_sha256"], digest)  # GET-rehash -> whole-object hex
        put_headers = next(h for m, h, _ in calls if m == "PUT")
        self.assertIn("authorization", put_headers)
        # PUT signs the real payload hash but sends no x-amz-checksum-* header
        # (R2 "Feature Not Implemented") and an explicit octet-stream Content-Type.
        self.assertNotIn("x-amz-checksum-sha256", put_headers)
        self.assertNotIn("x-amz-checksum-algorithm", put_headers)
        self.assertEqual(put_headers["content-length"], str(len(object_body)))
        self.assertEqual(put_headers["content-type"], "application/octet-stream")
        self.assertEqual(put_headers["x-amz-content-sha256"], digest)
        self.assertIn(
            "SignedHeaders=content-length;content-type;host;x-amz-content-sha256;x-amz-date",
            put_headers["authorization"],
        )
        # HEAD and GET both occur, in that order, for the after-verification.
        methods = [m for m, _, _ in calls]
        self.assertIn("HEAD", methods)
        self.assertIn("GET", methods)
        self.assertLess(methods.index("HEAD"), methods.index("GET"))

    def test_s3_transport_multipart_content_types_and_shape_via_fake_sender(self) -> None:
        # CreateMultipartUpload/UploadPart/CompleteMultipartUpload must carry the
        # correct Content-Type and body. CompleteMultipartUpload MUST NOT be
        # application/x-www-form-urlencoded (AWS forbids it); it is text/xml with a
        # <CompleteMultipartUpload> body of <Part><PartNumber><ETag> only (no
        # top-level <ChecksumSHA256>). CreateMultipartUpload sends no checksum
        # headers (SHA256 multipart is COMPOSITE-only; R2 marks the headers
        # unimplemented).
        s = archive_services
        calls = []

        def fake_send(*, method, url, headers, data_path=None, data_bytes=None):
            calls.append((method, dict(headers), url, data_bytes))
            if method == "POST" and "uploads" in url:
                return {"status": 200, "headers": {},
                        "body": b"<r><UploadId>up-9</UploadId></r>"}
            return {"status": 200, "headers": {"etag": '"e1"'}, "body": b""}

        cred = {
            "endpoint_host": "acct.r2.cloudflarestorage.com", "bucket": "b",
            "access_key_id": "AKIAEX", "secret_access_key": "s" * 40, "region": "auto",
        }
        t = s._object_storage_resolve_transport("cloudflare-r2", send=fake_send, credential=cred)
        upload_id = t.create_multipart(key="sha256/mp/x")
        self.assertEqual(upload_id, "up-9")
        part = t.put_part(key="sha256/mp/x", upload_id=upload_id, part_number=1, data=b"partbytes")
        completed = t.complete_multipart(
            key="sha256/mp/x", upload_id=upload_id, parts=[part], content_sha256="c" * 64
        )
        self.assertEqual(completed["status_class"], "ok")

        create_headers = next(h for m, h, u, _ in calls if m == "POST" and "uploads" in u)
        self.assertNotIn("x-amz-checksum-algorithm", create_headers)
        self.assertNotIn("x-amz-checksum-type", create_headers)
        part_headers = next(h for m, h, u, _ in calls if m == "PUT")
        self.assertEqual(part_headers["content-type"], "application/octet-stream")
        self.assertNotIn("x-amz-checksum-sha256", part_headers)
        complete_call = next((m, h, u, b) for m, h, u, b in calls if m == "POST" and "uploads" not in u)
        _, complete_headers, _, complete_body = complete_call
        self.assertEqual(complete_headers["content-type"], "text/xml")
        self.assertNotEqual(
            complete_headers["content-type"], "application/x-www-form-urlencoded"
        )
        body_text = complete_body.decode("utf-8")
        self.assertIn("<CompleteMultipartUpload>", body_text)
        self.assertIn("<Part><PartNumber>1</PartNumber><ETag>", body_text)
        self.assertNotIn("<ChecksumSHA256>", body_text)  # no top-level object checksum

    def test_complete_multipart_200_embedded_error_aborts_and_remains_retryable(self) -> None:
        s = archive_services
        calls = []

        def fake_send(*, method, url, headers, data_path=None, data_bytes=None):
            calls.append((method, url))
            if method == "POST" and "uploads" in url:
                return {"status": 200, "headers": {}, "body": b"<r><UploadId>up-error</UploadId></r>"}
            if method == "PUT":
                return {"status": 200, "headers": {"etag": '"part"'}, "body": b""}
            if method == "POST":
                return {"status": 200, "headers": {}, "body": b"<Error><Code>SlowDown</Code></Error>"}
            return {"status": 204, "headers": {}, "body": b""}

        cred = {
            "endpoint_host": "acct.r2.cloudflarestorage.com",
            "bucket": "b",
            "access_key_id": "AKIAEX",
            "secret_access_key": "s" * 40,
            "region": "auto",
        }
        transport = s._object_storage_resolve_transport("cloudflare-r2", send=fake_send, credential=cred)
        with tempfile.TemporaryDirectory() as tmp:
            data_path = Path(tmp) / "multipart.bin"
            data_path.write_bytes(b"abcdefgh")
            result, part_count = s._object_storage_multipart_put(
                transport=transport,
                key="sha256/mp/x",
                data_path=data_path,
                content_sha256=hashlib.sha256(b"abcdefgh").hexdigest(),
                part_size_bytes=4,
            )

        self.assertEqual(result["status_class"], "rate_limited")
        self.assertEqual(part_count, 2)
        self.assertEqual([method for method, _ in calls], ["POST", "PUT", "PUT", "POST", "DELETE"])
        self.assertIn("uploadId=up-error", calls[-1][1])

    def test_default_sender_preserves_explicit_content_type_no_socket(self) -> None:
        # Prove (without opening a socket) that the default sender does NOT let the
        # stdlib default a body-carrying request to application/x-www-form-urlencoded
        # when we set an explicit Content-Type. Intercepts urlopen to capture the
        # built Request; never touches the network.
        s = archive_services
        captured = {}

        class _FakeResp:
            status = 200
            headers = {}
            def read(self, size=-1): return b""
            def __enter__(self): return self
            def __exit__(self, *a): return False

        def fake_urlopen(req):
            captured["content_type"] = req.get_header("Content-type")
            captured["method"] = req.get_method()
            return _FakeResp()

        with patch.object(
            s.urllib.request,
            "build_opener",
            return_value=_FakeUrlOpener(fake_urlopen),
        ):
            sender = s._default_urllib_sender()
            sender(
                method="POST", url="https://acct.example/b/k?uploadId=1",
                headers={"content-type": "text/xml", "content-length": "3"},
                data_bytes=b"<x>",
            )
        self.assertEqual(captured["content_type"], "text/xml")
        self.assertNotEqual(captured["content_type"], "application/x-www-form-urlencoded")

    def test_default_sender_streams_data_path_in_bounded_replayable_chunks_no_socket(self) -> None:
        s = archive_services
        payload = (b"bounded-object-storage-" * 100_000) + b"tail"
        opened_read_sizes = []
        captured = {}

        class _GuardedFile(io.BytesIO):
            def read(self, size=-1):
                if size is None or size < 0 or size > s.OBJECT_STORAGE_HTTP_STREAM_CHUNK_BYTES:
                    raise AssertionError(f"unbounded path read: {size}")
                opened_read_sizes.append(size)
                return super().read(size)

            def __enter__(self):
                return self

            def __exit__(self, *args):
                self.close()
                return False

        class _FakeResp:
            status = 200
            headers = {}

            def read(self, size=-1):
                if size is None or size < 0:
                    raise AssertionError(f"unbounded response read: {size}")
                return b""

            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

        def fake_urlopen(req):
            handler = s.urllib.request.HTTPHandler()
            handler.parent = type("_Parent", (), {"addheaders": []})()
            req = handler.do_request_(req)
            captured["data_is_bytes"] = isinstance(req.data, (bytes, bytearray))
            captured["content_length"] = req.get_header("Content-length")
            captured["transfer_encoding"] = req.get_header("Transfer-encoding")
            captured["payload_hash"] = req.get_header("X-amz-content-sha256")
            captured["first"] = b"".join(req.data)
            captured["second"] = b"".join(req.data)
            return _FakeResp()

        with patch("builtins.open", side_effect=lambda *args, **kwargs: _GuardedFile(payload)):
            with patch.object(
                s.urllib.request,
                "build_opener",
                return_value=_FakeUrlOpener(fake_urlopen),
            ):
                sender = s._default_urllib_sender()
                response = sender(
                    method="PUT",
                    url="https://acct.example/b/k",
                    headers={
                        "content-length": str(len(payload)),
                        "content-type": "application/octet-stream",
                        "x-amz-content-sha256": hashlib.sha256(payload).hexdigest(),
                    },
                    data_path=Path("fixture.bin"),
                )

        self.assertEqual(response["status"], 200)
        self.assertFalse(captured["data_is_bytes"])
        self.assertEqual(captured["content_length"], str(len(payload)))
        self.assertIsNone(captured["transfer_encoding"])
        self.assertEqual(captured["payload_hash"], hashlib.sha256(payload).hexdigest())
        self.assertEqual(captured["first"], payload)
        self.assertEqual(captured["second"], payload)
        self.assertTrue(opened_read_sizes)
        self.assertTrue(all(0 < size <= s.OBJECT_STORAGE_HTTP_STREAM_CHUNK_BYTES for size in opened_read_sizes))

    def test_s3_transport_verification_get_hashes_bounded_chunks_without_raw_echo(self) -> None:
        s = archive_services
        marker = b"raw-object-secret-marker"
        payload = (b"verification-stream-" * 100_000) + marker
        get_read_sizes = []

        class _FakeResp:
            def __init__(self, body, *, headers):
                self.status = 200
                self.headers = headers
                self._body = io.BytesIO(body)

            def read(self, size=-1):
                if size is None or size < 0:
                    raise AssertionError(f"unbounded response read: {size}")
                get_read_sizes.append(size)
                return self._body.read(size)

            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

        responses = [
            _FakeResp(b"", headers={"content-length": str(len(payload))}),
            _FakeResp(payload, headers={"content-length": str(len(payload))}),
        ]

        def fake_urlopen(req):
            return responses.pop(0)

        cred = {
            "endpoint_host": "acct.r2.cloudflarestorage.com",
            "bucket": "b",
            "access_key_id": "AKIAEX",
            "secret_access_key": "s" * 40,
            "region": "auto",
        }
        with patch.object(
            s.urllib.request,
            "build_opener",
            return_value=_FakeUrlOpener(fake_urlopen),
        ):
            sender = s._default_urllib_sender()
            transport = s._object_storage_resolve_transport("cloudflare-r2", send=sender, credential=cred)
            result = transport.head_object(key="sha256/aa/" + hashlib.sha256(payload).hexdigest())

        self.assertEqual(result["size"], len(payload))
        self.assertEqual(result["checksum_sha256"], hashlib.sha256(payload).hexdigest())
        self.assertNotIn(marker.decode("ascii"), json.dumps(result))
        self.assertTrue(get_read_sizes)
        self.assertTrue(
            all(
                0 < size <= max(
                    s.OBJECT_STORAGE_HTTP_STREAM_CHUNK_BYTES,
                    s.OBJECT_STORAGE_HTTP_CONTROL_BODY_MAX_BYTES + 1,
                )
                for size in get_read_sizes
            )
        )
        self.assertTrue(any(size == s.OBJECT_STORAGE_HTTP_STREAM_CHUNK_BYTES for size in get_read_sizes))

    def test_incomplete_verification_get_never_deletes_uploaded_object(self) -> None:
        s = archive_services
        payload = b"complete-local-object"
        digest = hashlib.sha256(payload).hexdigest()
        methods = []
        head_count = 0

        class _FakeResp:
            def __init__(self, status, body=b"", headers=None):
                self.status = status
                self.headers = headers or {}
                self._body = io.BytesIO(body)

            def read(self, size=-1):
                if size is None or size < 0:
                    raise AssertionError(f"unbounded response read: {size}")
                return self._body.read(size)

            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

        def fake_urlopen(req):
            nonlocal head_count
            method = req.get_method()
            methods.append(method)
            if method == "HEAD":
                head_count += 1
                if head_count == 1:
                    return _FakeResp(404)
                return _FakeResp(200, headers={"content-length": str(len(payload))})
            if method == "PUT":
                self.assertEqual(b"".join(req.data), payload)
                return _FakeResp(200)
            if method == "GET":
                return _FakeResp(
                    200,
                    body=payload[:-3],
                    headers={"content-length": str(len(payload))},
                )
            return _FakeResp(200)

        cred = {
            "endpoint_host": "acct.r2.cloudflarestorage.com",
            "bucket": "b",
            "access_key_id": "AKIAEX",
            "secret_access_key": "s" * 40,
            "region": "auto",
        }
        with tempfile.TemporaryDirectory() as tmp:
            data_path = Path(tmp) / "object.bin"
            data_path.write_bytes(payload)
            ledger = s._ResumeLedger(Path(tmp) / "resume.jsonl")
            with patch.object(
                s.urllib.request,
                "build_opener",
                return_value=_FakeUrlOpener(fake_urlopen),
            ):
                sender = s._default_urllib_sender()
                transport = s._object_storage_resolve_transport("cloudflare-r2", send=sender, credential=cred)
                result = s._object_storage_execute_one_upload(
                    transport=transport,
                    key="sha256/aa/" + digest,
                    data_path=data_path,
                    size=len(payload),
                    content_sha256=digest,
                    multipart_threshold_bytes=1024 * 1024,
                    skip_uploaded=False,
                    ledger=ledger,
                    sleep=_NOOP_SLEEP,
                    rng=_ZERO_RNG,
                )

        self.assertEqual(result["result_status"], "failed_upload")
        self.assertEqual(methods, ["HEAD", "PUT", "HEAD", "GET"])
        self.assertNotIn("DELETE", methods)

