    def assert_quarantine_writer_fails_closed(
        self,
        archive_root: Path,
        *,
        command: str,
        lifecycle_action: str,
    ) -> dict[str, Any]:
        before = self.archive_tree_snapshot(archive_root)
        if command == "quarantine-foreign-block":
            arguments = [
                command,
                str(archive_root),
                "--plan",
                "workbench/historical-quarantine-plan.json",
            ]
        else:
            arguments = [
                command,
                str(archive_root),
                "--decision-preview",
                "workbench/historical-quarantine-decision.json",
            ]
        arguments.extend(
            [
                "--approve",
                "--reviewed-by",
                "person:fixed-gate-reviewer",
                "--format",
                "json",
            ]
        )
        code, output = self.run_cli(arguments)
        self.assertEqual(code, 1, output)
        result = json.loads(output)
        self.assertFalse(result["ok"], result)
        self.assertEqual(result["state"], "blocked")
        self.assertEqual(result["lifecycle_action"], lifecycle_action)
        self.assertEqual(
            result["reason_codes"],
            ["compound_exact_human_approval_binding_required"],
        )
        self.assertFalse(result["private_values_echoed"])
        self.assertEqual(self.archive_tree_snapshot(archive_root), before)
        return result

    def write_foreign_block_quarantine_case(
        self,
        archive_root: Path,
        case_id: str = "case-review-001",
    ) -> tuple[Path, Path, list[str]]:
        plan_path, artifact_path = self.write_foreign_block_quarantine_plan_report(archive_root, case_id)
        preview = archive_services.quarantine_foreign_block(
            archive_root,
            plan_path=archive_cli.archive_relative_path(plan_path, archive_root),
            dry_run=True,
        )
        self.assertTrue(preview["ok"], preview)
        reviewed_at = "2026-08-19T00:00:00Z"
        case_doc = json.loads(json.dumps(preview["quarantine_case_preview"]))
        receipt_doc = json.loads(json.dumps(preview["quarantine_write_receipt_preview"]))
        for document in (case_doc, receipt_doc):
            document["reviewed_by"] = "person:reviewer"
            document["reviewed_at"] = reviewed_at
        files_written = list(preview["would_change"])
        documents = {
            preview["proposed_paths"]["quarantine_case"]: case_doc,
            preview["proposed_paths"]["receipt"]: receipt_doc,
        }
        for relative, document in documents.items():
            destination = archive_root / Path(relative)
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(
                json.dumps(document, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
        return plan_path, artifact_path, files_written

