        reviewed_at = "2026-08-19T00:01:00Z"
        decision_record = json.loads(json.dumps(preview["quarantine_decision_record_preview"]))
        decision_receipt = json.loads(json.dumps(preview["quarantine_decision_receipt_preview"]))
        for document in (decision_record, decision_receipt):
            document["reviewed_by"] = "person:approver"
            document["reviewed_at"] = reviewed_at
        files_written = list(preview["would_change"])
        documents = {
            preview["proposed_paths"]["decision_record"]: decision_record,
            preview["proposed_paths"]["receipt"]: decision_receipt,
        }
        for relative, document in documents.items():
            destination = archive_root / Path(relative)
            destination.parent.mkdir(parents=True, exist_ok=True)
            destination.write_text(
                json.dumps(document, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
        result = {
            **preview,
            "dry_run": False,
            "approval_required": False,
            "approved": True,
            "reviewed_by": "person:approver",
            "reviewed_at": reviewed_at,
            "decision_status": "recorded_untrusted_decision",
            "files_written": files_written,
            "would_change": [],
            "quarantine_decision_record": decision_record,
            "quarantine_decision_receipt": decision_receipt,
        }
        return result, files_written

