    def test_write_text_atomic_survives_concurrent_writers_to_one_path(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "zet_probe.md"
            target.write_text("seed\n", encoding="utf-8")
            errors: list[str] = []

            def writer(marker: str) -> None:
                try:
                    for _ in range(60):
                        archive_services.write_text_atomic(target, marker * 2000 + "\n")
                except Exception as exc:  # noqa: BLE001 - the point is to see any of them
                    errors.append(f"{type(exc).__name__}: {exc}")

            threads = [
                threading.Thread(target=writer, args=("X",)),
                threading.Thread(target=writer, args=("Y",)),
            ]
            for thread in threads:
                thread.start()
            for thread in threads:
                thread.join()

            # A fixed <name>.tmp makes both writers share one temp file: one
            # replace() fails while the other still holds it open, or the loser's
            # cleanup unlinks the winner's temp mid-flight.
            self.assertEqual(errors, [])
            # Whoever won, the file is one writer's complete output, never a blend.
            final = target.read_text(encoding="utf-8")
            self.assertIn(final, {"X" * 2000 + "\n", "Y" * 2000 + "\n"})
            leftovers = [p.name for p in Path(tmp).iterdir() if p.name != target.name]
            self.assertEqual(leftovers, [])

    def test_archive_services_defines_no_top_level_name_twice(self) -> None:
        # v0.3.264 shipped a "fix" to write_bytes_atomic that never ran: the module
        # defined it twice and the later definition won, so the edited one was dead
        # code and 15 call sites inherited nothing. Reading the diff could not catch
        # that. This can.
        import ast

        source_path = Path(archive_services.__file__)
        tree = ast.parse(source_path.read_text(encoding="utf-8"))
        seen: dict[str, int] = {}
        duplicates: list[str] = []
        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                if node.name in seen:
                    duplicates.append(f"{node.name} (lines {seen[node.name]} and {node.lineno})")
                seen[node.name] = node.lineno
        self.assertEqual(duplicates, [], "shadowed top-level definitions in archive_services.py")

    def test_atomic_writers_bind_to_their_only_definition(self) -> None:
        # The companion to the AST sweep: what the module exports must be the
        # definition the file contains, so "I edited the function" and "the edited
        # function runs" cannot drift apart again.
        import ast
        import inspect

        source_path = Path(archive_services.__file__)
        tree = ast.parse(source_path.read_text(encoding="utf-8"))
        by_name = {
            node.name: node.lineno
            for node in tree.body
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        }
        for name in ("write_text_atomic", "write_bytes_atomic", "replace_with_retry"):
            bound = getattr(archive_services, name)
            self.assertEqual(
                inspect.getsourcelines(bound)[1],
                by_name[name],
                f"{name} does not bind to its definition in the source file",
            )
            self.assertIn("replace_with_retry", inspect.getsource(bound))

    def test_write_bytes_atomic_creates_parents_and_survives_concurrent_writers(self) -> None:
        # The byte writer had no direct test at all, which is exactly why an edit to
        # a shadowed copy of it went unnoticed. Both of its new behaviors are
        # covered here, mirroring the text-writer cases.
        with tempfile.TemporaryDirectory() as tmp:
            nested = Path(tmp) / "a" / "b" / "c.bin"
            archive_services.write_bytes_atomic(nested, b"payload\x00\xff")
            self.assertEqual(nested.read_bytes(), b"payload\x00\xff")
            self.assertEqual([p.name for p in nested.parent.iterdir()], ["c.bin"])

        with tempfile.TemporaryDirectory() as tmp:
            target = Path(tmp) / "zet_probe.bin"
            target.write_bytes(b"seed")
            errors: list[str] = []

            def writer(marker: bytes) -> None:
                try:
                    for _ in range(60):
                        archive_services.write_bytes_atomic(target, marker * 2000)
                except Exception as exc:  # noqa: BLE001
                    errors.append(f"{type(exc).__name__}: {exc}")

            threads = [
                threading.Thread(target=writer, args=(b"X",)),
                threading.Thread(target=writer, args=(b"Y",)),
            ]
            for thread in threads:
                thread.start()
            for thread in threads:
                thread.join()
            self.assertEqual(errors, [])
            self.assertIn(target.read_bytes(), {b"X" * 2000, b"Y" * 2000})
            self.assertEqual([p.name for p in Path(tmp).iterdir()], [target.name])

    def test_atomic_writers_are_byte_identical_to_the_plain_write(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            text = "---\nid: zet_x\ntitle: t\n---\n\nbody line\n"
            plain = Path(tmp) / "plain.md"
            atomic = Path(tmp) / "atomic.md"
            plain.write_text(text, encoding="utf-8")
            archive_services.write_text_atomic(atomic, text)
            # A no-change guard, not evidence that anything was fixed: it passes
            # against the pre-v0.3.264 writer too, and that is the point. The temp
            # file is opened without a newline= argument on purpose, so platform
            # newline translation is preserved exactly.
            self.assertEqual(atomic.read_bytes(), plain.read_bytes())
            # Pin the translation itself, so a regression that added newline="\n"
            # would fire on POSIX as well, where os.linesep == "\n" makes the
            # comparison above vacuous.
            self.assertEqual(
                atomic.read_bytes(), text.encode("utf-8").replace(b"\n", os.linesep.encode())
            )

            raw = b"\x00\x01binary\xff\n"
            plain_bytes = Path(tmp) / "plain.bin"
            atomic_bytes = Path(tmp) / "atomic.bin"
            plain_bytes.write_bytes(raw)
            archive_services.write_bytes_atomic(atomic_bytes, raw)
            self.assertEqual(atomic_bytes.read_bytes(), plain_bytes.read_bytes())
            self.assertEqual(atomic_bytes.read_bytes(), raw)

    def test_atomic_writers_create_missing_parents_and_leave_no_temp_files(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            nested = Path(tmp) / "a" / "b" / "c.md"
            archive_services.write_text_atomic(nested, "hello\n")
            self.assertEqual(nested.read_text(encoding="utf-8"), "hello\n")
            self.assertEqual([p.name for p in nested.parent.iterdir()], ["c.md"])

    def test_approved_edge_write_never_truncates_a_canonical_zet_in_place(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            offenders: list[str] = []

            def is_canonical(path_like: object) -> bool:
                try:
                    candidate = Path(path_like)  # type: ignore[arg-type]
                except TypeError:
                    return False
                return "zettels" in candidate.parts and candidate.suffix == ".md"

            real_write_text = Path.write_text
            real_write_bytes = Path.write_bytes
            real_open = Path.open

            # Watch every way a canonical zet could be truncated in place, not just
            # the one the removed code happened to use. The rollback in
            # zettel_edge_write only fires on OSError, so an interrupted in-place
            # write has no recovery at all.
            def guarded_write_text(self_path, *args, **kwargs):  # type: ignore[no-untyped-def]
                if is_canonical(self_path):
                    offenders.append(f"write_text:{self_path.name}")
                return real_write_text(self_path, *args, **kwargs)

            def guarded_write_bytes(self_path, *args, **kwargs):  # type: ignore[no-untyped-def]
                if is_canonical(self_path):
                    offenders.append(f"write_bytes:{self_path.name}")
                return real_write_bytes(self_path, *args, **kwargs)

            def guarded_open(self_path, mode="r", *args, **kwargs):  # type: ignore[no-untyped-def]
                if is_canonical(self_path) and any(flag in mode for flag in ("w", "a", "+")):
                    offenders.append(f"open({mode}):{self_path.name}")
                return real_open(self_path, mode, *args, **kwargs)

            with patch.object(Path, "write_text", guarded_write_text), patch.object(
                Path, "write_bytes", guarded_write_bytes
            ), patch.object(Path, "open", guarded_open):
                code, output = self.run_cli(
                    [
                        "zettel-edge",
                        str(archive_root),
                        "--from-zettel",
                        "zet_20240504_fake_lunch_thought",
                        "--target",
                        "zet_20110228_fake_school_record",
                        "--edge-type",
                        "semantic",
                        "--visibility",
                        "private",
                        "--approve",
                        "--reviewed-by",
                        "person:fixture-reviewer",
                        "--format",
                        "json",
                    ]
                )
            self.assertEqual(code, 0, output)
            self.assertEqual(json.loads(output)["write_status"], "written")
            self.assertEqual(offenders, [])
            # Assert on what is actually left behind, not on one temp naming
            # scheme: a grep for a suffix the writers no longer emit cannot fail.
            leftovers = [
                p.name for p in (archive_root / "zettels").iterdir() if not p.name.endswith(".md")
            ]
            self.assertEqual(leftovers, [])

    def _write_title_probe_zet(self, archive_root: Path, name: str, frontmatter: str) -> None:
        (archive_root / "zettels" / f"{name}.md").write_text(
            f"---\n{frontmatter}---\n\nbody text\n", encoding="utf-8"
        )

    def test_zet_title_readiness_separates_provenance_bound_from_shape_only(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            # Title is literally this record's own imported id, only formatted
            # differently. Provable from the zet alone.
            self._write_title_probe_zet(
                archive_root,
                "zet_probe_provenance",
                "id: ZETPROBEA\ntitle: 32634f642e1b80b68144d468b836da79\n"
                "status: canonical\nkind: note\n"
                "facets:\n  external_id: 32634f64-2e1b-80b6-8144-d468b836da79\n",
            )
            # Same shape, but nothing in frontmatter proves what it was meant to be.
            self._write_title_probe_zet(
                archive_root,
                "zet_probe_shape",
                "id: ZETPROBEB\ntitle: 24334f642e1b80ea9877f84bf54c4b0e\n"
                "status: canonical\nkind: note\n",
            )
            # Short hex-looking words are ordinary titles and must not trip the rule.
            self._write_title_probe_zet(
                archive_root,
                "zet_probe_ok",
                "id: ZETPROBEC\ntitle: deadbeef\nstatus: canonical\nkind: note\n",
            )

            code, output = self.run_cli(
                ["zet-title-readiness", str(archive_root), "--dry-run", "--format", "json"]
            )
            self.assertEqual(code, 0, output)
            result = json.loads(output)
            self.assertEqual(result["state"], "needs_attention")
            self.assertFalse(result["readiness_met"])
            # The signal counters overlap: the provenance-bound zet trips both
            # rules, so they are reported apart from the partition counts and do
            # not sum to a count of zets.
            self.assertEqual(result["signal_counts"]["title_matches_external_id"], 1)
            self.assertEqual(result["signal_counts"]["title_is_identifier_shaped"], 2)
            self.assertEqual(result["signal_counts"]["both_signals"], 1)
            self.assertEqual(result["attention"]["total_count"], 2)
            self.assertNotIn("title_matches_external_id", result["counts"])
            self.assertEqual(
                sum(result["counts"].values()) + result["attention"]["total_count"],
                result["canonical_zet_count"],
            )

            by_path = {item["path"]: item for item in result["attention"]["items"]}
            provenance = by_path["zettels/zet_probe_provenance.md"]
            self.assertTrue(provenance["provenance_bound"])
            self.assertIn("title_matches_external_id", provenance["signals"])
            shape_only = by_path["zettels/zet_probe_shape.md"]
            self.assertFalse(shape_only["provenance_bound"])
            self.assertEqual(shape_only["signals"], ["title_is_identifier_shaped"])
            self.assertNotIn("zettels/zet_probe_ok.md", by_path)

    def test_zet_title_readiness_never_echoes_title_or_identifier_values(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            identifier = "32634f642e1b80b68144d468b836da79"
            # The house mints a zet id -- and therefore its filename -- from the
            # title, so an attention row can carry the very value this census
            # withholds. A hand-named fixture closes that channel by construction
            # and proves nothing; these reproduce the real derivations.
            minted = f"zet_20260726_120000_{identifier}"
            self._write_title_probe_zet(
                archive_root,
                minted,
                f"id: {minted}\ntitle: {identifier}\n"
                "status: canonical\nkind: note\n"
                "facets:\n  external_id: 32634f64-2e1b-80b6-8144-d468b836da79\n",
            )
            # An importer may also set the bare identifier as the draft id, which
            # reaches canonical as the filename with no zet_ prefix to gate on.
            self._write_title_probe_zet(
                archive_root,
                identifier,
                f"id: {identifier}\ntitle: {identifier}\n"
                "status: canonical\nkind: note\n",
            )
            # The mint truncates its slug at 32 characters, so a dashed uuid title
            # leaves a long prefix rather than the whole value in the filename.
            # A partial identifier is still the identifier.
            truncated = "zet_20260726_120001_9f41ab07_6c22_4d15_9e33_70bb1c5a"
            self._write_title_probe_zet(
                archive_root,
                truncated,
                f"id: {truncated}\ntitle: 9f41ab07-6c22-4d15-9e33-70bb1c5ad284\n"
                "status: canonical\nkind: note\n",
            )

            code, output = self.run_cli(
                ["zet-title-readiness", str(archive_root), "--dry-run", "--format", "json"]
            )
            self.assertEqual(code, 0, output)
            # The offending value is the thing a report is most tempted to print.
            self.assertNotIn(identifier, output)
            self.assertNotIn("32634f64-2e1b-80b6", output)
            self.assertNotIn("9f41ab07", output)
            result = json.loads(output)
            self.assertFalse(result["privacy_guards"]["title_values_echoed"])
            self.assertFalse(result["privacy_guards"]["external_id_values_echoed"])
            self.assertFalse(result["privacy_guards"]["writes"])
            self.assertEqual(result["would_change"], [])

            # Withholding is disclosed rather than silent, so an operator can tell
            # a clean report from a suppressed one.
            attention = result["attention"]
            self.assertEqual(attention["total_count"], 3)
            self.assertEqual(attention["paths_withheld_count"], 3)
            self.assertEqual(attention["zettel_ids_withheld_count"], 3)
            for item in attention["items"]:
                self.assertIsNone(item["path"])
                self.assertIsNone(item["zettel_id"])
                self.assertEqual(item["path_withheld_reason"], "discloses_title")
                self.assertEqual(item["zettel_id_withheld_reason"], "discloses_title")

    def test_zet_title_readiness_keeps_references_that_cannot_disclose(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            # Importer-minted names digest the source record rather than the title
            # (external_import_zettel_id), so they cannot disclose it. Withholding
            # must not fire here, or the census stops being actionable for exactly
            # the imported population it exists to report on.
            name = "zet_import_notion_a1b2c3d4e5f60718"
            self._write_title_probe_zet(
                archive_root,
                name,
                f"id: {name}\ntitle: 32634f642e1b80b68144d468b836da79\n"
                "status: canonical\nkind: note\n",
            )
            code, output = self.run_cli(
                ["zet-title-readiness", str(archive_root), "--dry-run", "--format", "json"]
            )
            self.assertEqual(code, 0, output)
            result = json.loads(output)
            attention = result["attention"]
            self.assertEqual(attention["total_count"], 1)
            self.assertEqual(attention["paths_withheld_count"], 0)
            self.assertEqual(attention["zettel_ids_withheld_count"], 0)
            item = attention["items"][0]
            self.assertEqual(item["path"], f"zettels/{name}.md")
            self.assertEqual(item["zettel_id"], name)
            self.assertIsNone(item["path_withheld_reason"])
            self.assertIsNone(item["zettel_id_withheld_reason"])
            # The digest in that name is a 16-character hex run. A shape-only rule
            # would suppress it; the rule is title-relative, so it does not.
            self.assertIn("a1b2c3d4e5f60718", output)

    def test_zet_title_readiness_is_read_only_and_excludes_redacted(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            self._write_title_probe_zet(
                archive_root,
                "zet_probe_redacted",
                "id: ZETPROBEE\ntitle: 32634f642e1b80b68144d468b836da79\n"
                "status: redacted\nkind: note\n",
            )
            before = self.snapshot_archive_files(archive_root)

            code, output = self.run_cli(["zet-title-readiness", str(archive_root), "--format", "json"])
            self.assertEqual(code, 1)
            self.assertIn("requires --dry-run", output)

            code, output = self.run_cli(
                ["zet-title-readiness", str(archive_root), "--dry-run", "--format", "json"]
            )
            self.assertEqual(code, 0, output)
            result = json.loads(output)
            # A redacted zet exposes no title to judge and must not be accused.
            self.assertEqual(result["counts"]["redacted"], 1)
            self.assertEqual(result["signal_counts"]["title_is_identifier_shaped"], 0)
            self.assertEqual(result["state"], "ready")
            self.assertTrue(result["readiness_met"])
            self.assertEqual(self.snapshot_archive_files(archive_root), before)

    def _write_title_remap_proposal(self, archive_root: Path, rows: list[dict]) -> str:
        relative = ".wom-scratch/title-remap/reviewed.jsonl"
        path = archive_root / ".wom-scratch" / "title-remap" / "reviewed.jsonl"
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            "".join(json.dumps(row, ensure_ascii=False) + "\n" for row in rows),
            encoding="utf-8",
        )
        return relative

    def _canonical_sha256(self, archive_root: Path, name: str) -> str:
        data = (archive_root / "zettels" / f"{name}.md").read_bytes()
        return "sha256:" + hashlib.sha256(data).hexdigest()

    def _create_title_remap_write_fixture(
        self,
        archive_root: Path,
        *,
        count: int,
        proposal_name: str,
    ) -> dict[str, Any]:
        rows: list[dict[str, Any]] = []
        originals: dict[Path, bytes] = {}
        for index in range(count):
            identifier = f"32634f642e1b80b68144d468b836da{index + 121:02x}"
            notion_page_id = (
                f"{identifier[:8]}-{identifier[8:12]}-{identifier[12:16]}-"
                f"{identifier[16:20]}-{identifier[20:]}"
            )
            name = f"zet_title_write_failure_probe_{index + 1}"
            self._write_title_probe_zet(
                archive_root,
                name,
                f"id: {name}\ntitle: {identifier}\n"
                "status: canonical\nkind: note\n"
                f"facets:\n  notion_page_id: {notion_page_id}\n",
            )
            canonical_path = archive_root / "zettels" / f"{name}.md"
            before_bytes = canonical_path.read_bytes()
            originals[canonical_path] = before_bytes
            rows.append(
                {
                    "schema": "wom-kit/zet-title-remap-proposal/v0.1",
                    "zettel_id": name,
                    "expected_file_sha256": (
                        "sha256:" + hashlib.sha256(before_bytes).hexdigest()
                    ),
                    "title": f"검토를 마친 안전한 제목 {index + 1}",
                    "basis": "human_written",
                }
            )
        proposal_relative = self._write_title_remap_proposal(
            archive_root,
            rows,
        )
        proposal_path = archive_root.joinpath(
            *PurePosixPath(proposal_relative).parts
        )
        renamed_proposal_relative = (
            f".wom-scratch/title-remap/{proposal_name}"
        )
        renamed_proposal_path = archive_root.joinpath(
            *PurePosixPath(renamed_proposal_relative).parts
        )
        renamed_proposal_path.parent.mkdir(parents=True, exist_ok=True)
        proposal_path.replace(renamed_proposal_path)
        plan = archive_services.zet_title_remap_plan(
            archive_root,
            proposal_path=renamed_proposal_relative,
            max_items=count,
            dry_run=True,
        )
        self.assertTrue(plan["ok"], plan)
        dry_result = archive_services.zet_title_remap_write(
            archive_root,
            proposal_path=renamed_proposal_relative,
            expected_proposal_sha256=plan["proposal"]["sha256"],
            expected_plan_digest=plan["plan_digest"],
            max_items=count,
            dry_run=True,
        )
        self.assertEqual(dry_result["status"], "ready_to_apply", dry_result)
        return {
            "relative": renamed_proposal_relative,
            "path": renamed_proposal_path,
            "proposal_sha256": plan["proposal"]["sha256"],
            "plan_digest": plan["plan_digest"],
            "write_plan_digest": dry_result["write_plan_digest"],
            "originals": originals,
            "rows": rows,
        }

