    def install_historical_title_remap_revert_fixture(
        self,
        archive_root: Path,
        fixture: dict[str, Any],
        *,
        state: str = "completed",
        reviewed_by: str = "person:revert-fixture-reviewer",
    ) -> dict[str, Any]:
        """Install bounded v0.3 title-revert evidence without its writer."""

        if state not in {
            "prepared",
            "partially_reverted",
            "fully_reverted_receipt_missing",
            "completed",
            "stale_completed",
        }:
            raise AssertionError(f"unsupported historical title revert state: {state}")
        root = archive_services.require_existing_archive_root(archive_root)
        applied = self.install_historical_title_remap_write_fixture(
            root,
            fixture,
            state="completed",
            reviewed_by="person:revert-fixture-source",
        )
        source_receipt = applied["receipt_document"]
        source_receipt_path = applied["receipt_path"]
        source_receipt_relative = archive_services.archive_relative_path(
            source_receipt_path,
            root,
        )
        source_receipt_sha256 = (
            "sha256:" + hashlib.sha256(source_receipt_path.read_bytes()).hexdigest()
        )
        revert_plan = archive_services.zet_title_remap_revert_plan(
            root,
            receipt_path=source_receipt_relative,
            expected_receipt_sha256=source_receipt_sha256,
            max_items=len(source_receipt["items"]),
            dry_run=True,
        )
        self.assertTrue(revert_plan["ok"], revert_plan)
        title_remap_root = root / ".wom-scratch" / "title-remap"
        title_remap_root.mkdir(parents=True, exist_ok=True)
        journal_path = (
            archive_services.zet_title_remap_revert_transaction_journal_path(
                title_remap_root,
                source_receipt_sha256,
            )
        )
        receipt_relative = (
            archive_services.zet_title_remap_revert_receipt_relative_path(
                source_receipt_sha256
            )
        )
        reverted_at = "2026-07-27T12:30:00Z"
        journal = {
            "schema": archive_services.ZET_TITLE_REMAP_REVERT_TRANSACTION_JOURNAL_SCHEMA,
            "action": "zet_title_remap_revert_transaction",
            "status": "prepared",
            "operation": "revert",
            "prepared_at": reverted_at,
            "archive_id": archive_services.read_archive_id(root),
            "source_receipt_path": source_receipt_relative,
            "source_receipt_sha256": source_receipt_sha256,
            "planner_wom_kit_version": archive_services.WOM_KIT_VERSION,
            "source_history_audit_digest": revert_plan["history_audit"]["digest"],
            "revert_plan_digest": revert_plan["plan_digest"],
            "reviewed_by": reviewed_by,
            "human_affirmations": {
                "all_title_reversions_reviewed": True,
                "archive_quiescence_confirmed": True,
            },
            "final_receipt_path": receipt_relative,
            "item_count": source_receipt["item_count"],
            "items": source_receipt["items"],
            "recovery_contract": {
                "journal_published_before_first_canonical_write": True,
                "current_state_inferred_from_participant_hashes": True,
                "prior_byte_snapshots_verified_before_journal": True,
                "automatic_resume_implemented": False,
                "automatic_rollback_after_hard_exit_implemented": False,
            },
            "privacy_guards": {
                "old_title_text_stored": False,
                "new_title_text_stored": False,
                "body_text_stored": False,
                "contains_private_zettel_ids_and_paths": True,
                "provider_api_called": False,
                "model_called": False,
                "secret_store_or_environment_read": False,
            },
        }
        journal["journal_digest"] = archive_services.sha256_json_value(journal)
        self.assertTrue(
            archive_services.zet_title_remap_revert_transaction_journal_document_valid(
                journal
            )
        )
        receipt = archive_services.zet_title_remap_revert_receipt_from_journal(
            journal,
            source_receipt,
            source_receipt_path=source_receipt_relative,
            source_receipt_sha256=source_receipt_sha256,
        )
        self.assertTrue(
            archive_services.zet_title_remap_revert_receipt_document_valid(receipt)
        )
        lock_path = title_remap_root / ".title-remap.write.lock"
        lock = archive_services.zet_title_remap_revert_write_lock_document(
            journal_path,
            journal,
        )
        retained_states = {
            "prepared",
            "partially_reverted",
            "fully_reverted_receipt_missing",
            "stale_completed",
        }
        if state in retained_states:
            journal_path.write_text(
                json.dumps(journal, ensure_ascii=False, separators=(",", ":")) + "\n",
                encoding="utf-8",
            )
            lock_path.write_text(
                json.dumps(lock, ensure_ascii=False, separators=(",", ":")) + "\n",
                encoding="utf-8",
            )
        candidates: list[dict[str, Any]] = []
        for item in source_receipt["items"]:
            path = root.joinpath(*PurePosixPath(item["canonical_path"]).parts)
            snapshot_path = root.joinpath(
                *PurePosixPath(item["before_snapshot"]["logical_key"]).parts
            )
            candidates.append(
                {
                    "path": path,
                    "applied_bytes": path.read_bytes(),
                    "reverted_bytes": snapshot_path.read_bytes(),
                }
            )
        if state in {
            "partially_reverted",
            "fully_reverted_receipt_missing",
            "completed",
            "stale_completed",
        }:
            count = 1 if state == "partially_reverted" else len(candidates)
            for candidate in candidates[:count]:
                candidate["path"].write_bytes(candidate["reverted_bytes"])
        receipt_path = root.joinpath(*PurePosixPath(receipt_relative).parts)
        if state in {"completed", "stale_completed"}:
            receipt_path.parent.mkdir(parents=True, exist_ok=True)
            receipt_path.write_text(
                json.dumps(receipt, ensure_ascii=False, separators=(",", ":")) + "\n",
                encoding="utf-8",
            )
        return {
            "fixture": fixture,
            "applied": applied,
            "source_receipt": source_receipt,
            "receipt_relative": source_receipt_relative,
            "receipt_sha256": source_receipt_sha256,
            "revert_plan": revert_plan,
            "revert_receipt": receipt,
            "revert_receipt_path": receipt_path,
            "title_remap_root": title_remap_root,
            "journal": journal,
            "journal_path": journal_path,
            "lock": lock,
            "lock_path": lock_path,
            "candidates": candidates,
        }

