    def test_zet_title_remap_candidate_replaces_exact_scalar_and_rejects_duplicates(
        self,
    ) -> None:
        replacement = "Reviewed: title #1"
        samples = [
            b"---\nid: zet_x\ntitle: abcdef1234567890\nstatus: canonical\nkind: note\n---\nbody\n",
            (
                "---\r\nid: zet_x\r\ntitle: \"abcdef1234567890\"\r\n"
                "status: canonical\r\nkind: note\r\n---\r\nbody\r\n"
            ).encode("utf-8"),
            (
                "\ufeff---\nid: zet_x\ntitle: |\n  abcdef1234567890\n"
                "status: canonical\nkind: note\n---\nbody\n"
            ).encode("utf-8"),
            (
                "---\nid: zet_x\ntitle: >-\n  abcdef1234567890\n"
                "status: canonical\nkind: note\n---\nbody\n"
            ).encode("utf-8"),
        ]
        for raw in samples:
            with self.subTest(raw=raw[:30]):
                before_frontmatter, before_body = (
                    archive_services.split_zettel_text(raw.decode("utf-8"))
                )
                candidate = archive_services.zet_title_remap_candidate_bytes(
                    raw,
                    replacement,
                )
                after_frontmatter, after_body = (
                    archive_services.split_zettel_text(
                        candidate.decode("utf-8")
                    )
                )
                self.assertEqual(after_frontmatter["title"], replacement)
                before_frontmatter.pop("title")
                after_frontmatter.pop("title")
                self.assertEqual(after_frontmatter, before_frontmatter)
                self.assertEqual(after_body, before_body)
                self.assertEqual(
                    candidate.startswith(b"\xef\xbb\xbf"),
                    raw.startswith(b"\xef\xbb\xbf"),
                )
                self.assertEqual(b"\r\n" in candidate, b"\r\n" in raw)

        duplicate = (
            b"---\nid: zet_x\ntitle: abcdef1234567890\n"
            b"title: fedcba0987654321\nstatus: canonical\nkind: note\n---\nbody\n"
        )
        with self.assertRaises(archive_services.ArchiveServiceError):
            archive_services.zet_title_remap_candidate_bytes(
                duplicate,
                replacement,
            )

    def test_zet_title_remap_write_preserves_prior_bytes_and_is_idempotent(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            fixture = self._create_title_remap_write_fixture(
                archive_root,
                count=1,
                proposal_name="approved-private-title-remap.jsonl",
            )
            before = self.archive_tree_snapshot(archive_root)
            code, output = self.run_cli(
                [
                    "zet-title-remap-write",
                    str(archive_root),
                    "--proposal",
                    fixture["relative"],
                    "--expected-proposal-sha256",
                    fixture["proposal_sha256"],
                    "--expected-plan-digest",
                    fixture["plan_digest"],
                    "--expected-write-plan-digest",
                    fixture["write_plan_digest"],
                    "--approve",
                    "--reviewed-by",
                    "person:title-remap-fixed-gate-reviewer",
                    "--affirm-titles-reviewed",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(code, 1, output)
            result = json.loads(output)
            self.assertFalse(result["ok"])
            self.assertEqual(result["state"], "blocked")
            self.assertEqual(result["lifecycle_action"], "zet_title_remap_write")
            self.assertEqual(
                result["reason_codes"],
                ["compound_exact_human_approval_binding_required"],
            )
            self.assertFalse(result["private_values_echoed"])
            self.assertEqual(self.archive_tree_snapshot(archive_root), before)
            for private_value in (
                fixture["proposal_sha256"],
                fixture["rows"][0]["zettel_id"],
                fixture["rows"][0]["title"],
            ):
                self.assertNotIn(private_value, output)

    def test_zet_title_remap_revert_plan_binds_completed_receipt_without_writing(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            fixture = self._create_title_remap_write_fixture(
                archive_root,
                count=2,
                proposal_name="completed-revert-plan.jsonl",
            )
            historical = self.install_historical_title_remap_source_for_revert(
                archive_root,
                fixture,
                reviewed_by="person:title-revert-plan-reviewer",
            )
            before = self.archive_tree_snapshot(archive_root)
            result = archive_services.zet_title_remap_revert_plan(
                archive_root,
                receipt_path=historical["receipt_relative"],
                expected_receipt_sha256=historical["receipt_sha256"],
                max_items=2,
                dry_run=True,
            )
            self.assertTrue(result["ok"], result)
            self.assertEqual(result["status"], "ready_for_human_review")
            self.assertRegex(result["plan_digest"], r"^sha256:[0-9a-f]{64}$")
            self.assertEqual(result["summary"]["candidate_count"], 2)
            self.assertEqual(result["summary"]["prior_byte_snapshots_verified"], 2)
            self.assertEqual(
                result["summary"]["deterministic_title_only_inverses_verified"],
                2,
            )
            self.assertTrue(result["history_audit"]["complete"])
            self.assertTrue(result["history_audit"]["healthy"])
            self.assertFalse(result["write_boundary"]["files_written"])
            self.assertEqual(self.archive_tree_snapshot(archive_root), before)
            serialized = json.dumps(result, ensure_ascii=False)
            for row in fixture["rows"]:
                self.assertNotIn(row["zettel_id"], serialized)
