    def test_zet_title_remap_plan_blocks_stale_bytes_and_identifier_replacements(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            stale = "zet_import_notion_d4e5f60718293041"
            reshape = "zet_import_notion_e5f6071829304152"
            for name in (stale, reshape):
                self._write_title_probe_zet(
                    archive_root,
                    name,
                    f"id: {name}\ntitle: 24334f642e1b80ea9877f84bf54c4b0e\n"
                    "status: canonical\nkind: note\n",
                )
            stale_sha = self._canonical_sha256(archive_root, stale)
            # The zet changed after the operator built the proposal.
            (archive_root / "zettels" / f"{stale}.md").write_text(
                f"---\nid: {stale}\ntitle: 24334f642e1b80ea9877f84bf54c4b0e\n"
                "status: canonical\nkind: note\n---\n\nbody text edited later\n",
                encoding="utf-8",
            )
            proposal = self._write_title_remap_proposal(
                archive_root,
                [
                    {
                        "schema": "wom-kit/zet-title-remap-proposal/v0.1",
                        "zettel_id": stale,
                        "expected_file_sha256": stale_sha,
                        "title": "Startup club meeting notes for the spring term",
                        "basis": "source_export_property",
                    },
                    {
                        "schema": "wom-kit/zet-title-remap-proposal/v0.1",
                        "zettel_id": reshape,
                        "expected_file_sha256": self._canonical_sha256(archive_root, reshape),
                        # Replacing one identifier with another leaves the archive
                        # exactly as unbrowsable as before.
                        "title": "9f41ab076c224d159e3370bb1c5ad284",
                        "basis": "source_export_property",
                    },
                ],
            )
            code, output = self.run_cli(
                ["zet-title-remap-plan", str(archive_root), "--proposal", proposal, "--dry-run"]
            )
            self.assertEqual(code, 1)
            result = json.loads(output)
            self.assertEqual(result["summary"]["ready_for_review_count"], 0)
            self.assertEqual(result["summary"]["blocked_count"], 2)
            by_row = {item["row_index"]: item["blocker_codes"] for item in result["items"]}
            self.assertIn("canonical_file_sha256_mismatch", by_row[0])
            self.assertIn("title_is_identifier_shaped", by_row[1])

    def test_zet_title_readiness_does_not_claim_readiness_over_unjudged_zets(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            # Frontmatter this census could not read is not evidence of a good
            # title. Counting it as human-readable would claim a check never ran.
            (archive_root / "zettels" / "zet_probe_broken.md").write_text(
                "---\nid: ZETPROBEF\ntitle: [unclosed\nstatus: canonical\n---\n\nbody\n",
                encoding="utf-8",
            )
            code, output = self.run_cli(
                ["zet-title-readiness", str(archive_root), "--dry-run", "--format", "json"]
            )
            self.assertEqual(code, 0, output)
            result = json.loads(output)
            self.assertEqual(result["attention"]["total_count"], 0)
            self.assertEqual(result["counts"]["frontmatter_unreadable"], 1)
            self.assertEqual(result["readiness"]["unjudged_count"], 1)
            # No attention rows, but the census still cannot call the archive ready.
            self.assertFalse(result["readiness_met"])
            self.assertFalse(result["readiness"]["all_titles_human_readable"])
            self.assertEqual(result["state"], "needs_attention")
            self.assertIn(
                "Canonical zets whose frontmatter could not be read.",
                result["claim_boundary"]["not_checked"],
            )
            # A finding is not a command failure.
            self.assertFalse(result["exit_policy"]["needs_attention_is_command_failure"])
            self.assertEqual(result["blockers"], [])
            self.assertEqual(result["warnings"], [])

    def test_first_read_readiness_requires_explicit_abstracts_without_echoing_content(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            private_markers: list[str] = []

            missing_code, missing_output = self.run_cli(
                ["first-read-readiness", str(archive_root), "--format", "json"]
            )
            self.assertEqual(missing_code, 1)
            self.assertIn("requires --dry-run", missing_output)

            code, output = self.run_cli(
                [
                    "first-read-readiness",
                    str(archive_root),
                    "--dry-run",
                    "--max-items",
                    "2",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(code, 0, output)
            result = json.loads(output)
            self.assertTrue(result["ok"])
            self.assertEqual(result["state"], "needs_attention")
            self.assertFalse(result["readiness_met"])
            self.assertEqual(result["schema"], "wom-kit/first-read-readiness/v0.2")
            self.assertTrue(result["exit_policy"]["zero_when_diagnostic_completed"])
            self.assertFalse(result["exit_policy"]["needs_attention_is_command_failure"])
            self.assertEqual(result["canonical_zet_count"], 4)
            self.assertEqual(result["abstract_coverage"]["counts"]["missing"], 4)
            self.assertFalse(result["readiness"]["all_required_explicit_abstracts_present"])
            self.assertFalse(result["readiness"]["first_read_surface_ready"])
            self.assertEqual(result["attention"]["returned_count"], 2)
            self.assertTrue(result["attention"]["truncated"])
            self.assertFalse(result["scan"]["zettel_bodies_read"])
            self.assertFalse(result["privacy_guards"]["abstract_text_echoed"])
            self.assertFalse(result["privacy_guards"]["title_values_echoed"])

            text_code, text_output = self.run_cli(
                [
                    "first-read-readiness",
                    str(archive_root),
                    "--dry-run",
                    "--max-items",
                    "2",
                    "--format",
                    "text",
                ]
            )
            self.assertEqual(text_code, 0, text_output)
            self.assertIn(
                "Command completed: yes; readiness attention is not a command failure.",
                text_output,
            )

            for index, path in enumerate(sorted((archive_root / "zettels").glob("*.md"))):
                frontmatter, body = archive_services.split_zettel_text(path.read_text(encoding="utf-8"))
                marker = f"PRIVATE_EXPLICIT_ABSTRACT_{index}"
                private_markers.append(marker)
                frontmatter["abstract"] = marker
                path.write_text(
                    "---\n" + archive_cli.dump_yaml(frontmatter) + "---\n\n" + body,
                    encoding="utf-8",
                )

            ready_code, ready_output = self.run_cli(
                ["memory-readiness", str(archive_root), "--dry-run", "--format", "json"]
            )
            self.assertEqual(ready_code, 0, ready_output)
            ready = json.loads(ready_output)
            self.assertTrue(ready["ok"])
