    def test_validated_approval_zettel_snapshot_rejects_without_exposing_bytes(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            canonical_path = sorted((archive_root / "zettels").glob("*.md"))[0]
            original = canonical_path.read_bytes()
            original_text = original.decode("utf-8")
            archive_id = archive_services.read_archive_id(archive_root)
            zettel_id = canonical_path.stem
            duplicate_status = original_text.replace(
                "status: canonical",
                "status: canonical\nstatus: redacted",
                1,
            ).encode("utf-8")
            invalid_schema = re.sub(
                r"(?m)^title:.*$", "title: []", original_text, count=1
            ).encode("utf-8")
            redacted = original_text.replace(
                "status: canonical", "status: redacted", 1
            ).encode("utf-8")
            cases = (
                (
                    "malformed_boundary",
                    b"PRIVATE MALFORMED BODY WITHOUT FRONTMATTER\n",
                    zettel_id,
                    archive_id,
                    "canonical",
                    len(original) + 1024,
                    "frontmatter_boundary_invalid",
                ),
                (
                    "invalid_utf8",
                    b"---\nid: zet_invalid\nstatus: canonical\n---\n\n\xff\n",
                    zettel_id,
                    archive_id,
                    "canonical",
                    len(original) + 1024,
                    "frontmatter_unicode_error",
                ),
                (
                    "duplicate_yaml_key",
                    duplicate_status,
                    zettel_id,
                    archive_id,
                    "canonical",
                    len(duplicate_status) + 1,
                    "frontmatter_duplicate_key",
                ),
                (
                    "schema_invalid",
                    invalid_schema,
                    zettel_id,
                    archive_id,
                    "canonical",
                    len(invalid_schema) + 1,
                    "frontmatter_schema_invalid",
                ),
                (
                    "redacted",
                    redacted,
                    zettel_id,
                    archive_id,
                    "canonical",
                    len(redacted) + 1,
                    "frontmatter_status_mismatch",
                ),
                (
                    "wrong_id",
                    original,
                    "zet_wrong_expected_identity",
                    archive_id,
                    "canonical",
                    len(original) + 1,
                    "frontmatter_identity_mismatch",
                ),
                (
                    "wrong_archive",
                    original,
                    zettel_id,
                    "archive:personal:wrong",
                    "canonical",
                    len(original) + 1,
                    "frontmatter_archive_identity_mismatch",
                ),
                (
                    "wrong_status",
                    original,
                    zettel_id,
                    archive_id,
                    "draft",
                    len(original) + 1,
                    "frontmatter_status_mismatch",
                ),
                (
                    "oversize",
                    original,
                    zettel_id,
                    archive_id,
                    "canonical",
                    len(original) - 1,
                    "zettel_size_limit_exceeded",
                ),
            )
            for (
                name,
                raw_bytes,
                expected_id,
                expected_archive,
                expected_status,
                max_bytes,
                expected_issue,
            ) in cases:
                with self.subTest(name=name):
                    canonical_path.write_bytes(raw_bytes)
                    snapshot = archive_services.validated_approval_zettel_snapshot(
                        canonical_path,
                        max_bytes=max_bytes,
                        expected_zettel_id=expected_id,
                        expected_archive_id=expected_archive,
                        expected_status=expected_status,
                    )
                    self.assertFalse(snapshot["ok"], snapshot)
                    self.assertIn(expected_issue, snapshot["issue_codes"])
                    self.assertIsNone(snapshot["bytes"])
                    self.assertEqual(snapshot["frontmatter"], {})
                    self.assertEqual(snapshot["body"], "")

            canonical_path.write_bytes(original)
            valid = archive_services.validated_approval_zettel_snapshot(
                canonical_path,
                max_bytes=len(original),
                expected_zettel_id=zettel_id,
                expected_archive_id=archive_id,
                expected_status="canonical",
            )
            self.assertTrue(valid["ok"], valid)
            self.assertEqual(valid["bytes"], original)

            unquoted_timestamps = re.sub(
                r'(?m)^(created_at|updated_at): "([^"]+)"$',
                r"\1: \2",
                original_text,
            ).encode("utf-8")
            canonical_path.write_bytes(unquoted_timestamps)
            compatible_timestamp_snapshot = (
                archive_services.validated_approval_zettel_snapshot(
                    canonical_path,
                    max_bytes=len(unquoted_timestamps),
                    expected_zettel_id=zettel_id,
                    expected_archive_id=archive_id,
                    expected_status="canonical",
                )
            )
            self.assertTrue(
                compatible_timestamp_snapshot["ok"],
                compatible_timestamp_snapshot,
            )
            self.assertIsInstance(
                compatible_timestamp_snapshot["frontmatter"]["created_at"], str
            )
            self.assertIsInstance(
                compatible_timestamp_snapshot["frontmatter"]["updated_at"], str
            )

    def test_validated_approval_snapshot_rejects_non_json_yaml_trees_before_hashing(
        self,
    ) -> None:
        yaml_fragments = {
            "cyclic_alias": "approval_cycle: &approval_cycle [*approval_cycle]",
            "non_string_key": "1: hidden",
            "yaml_set": "approval_custom: !!set {a: null}",
            "yaml_binary": "approval_custom: !!binary SGVsbG8=",
            "non_finite_float": "approval_custom: .nan",
            "excessive_depth": (
                "approval_custom: " + "[" * 66 + "null" + "]" * 66
            ),
        }
        for name, fragment in yaml_fragments.items():
            with self.subTest(name=name), tempfile.TemporaryDirectory() as tmp:
                archive_root = self.copy_fake_archive(Path(tmp) / "archive")
                fixture = self.create_zet_revision_proposal(archive_root)
                proposal_text = fixture["proposal_path"].read_text(encoding="utf-8")
                fixture["proposal_path"].write_text(
                    proposal_text.replace(
                        "\n---\n\n",
                        f"\n{fragment}\n---\n\n",
                        1,
                    ),
                    encoding="utf-8",
                )

                snapshot = archive_services.validated_zet_revision_snapshot(
                    fixture["proposal_path"],
                    expected_zettel_id=fixture["zettel_id"],
                    expected_archive_id=archive_services.read_archive_id(archive_root),
                )
                self.assertFalse(snapshot["ok"], snapshot)
                self.assertIn("frontmatter_yaml_invalid", snapshot["issue_codes"])
                self.assertIsNone(snapshot["bytes"])
                self.assertEqual(snapshot["frontmatter"], {})
                self.assertEqual(snapshot["body"], "")

                with patch.object(
                    archive_services.hashlib,
                    "sha256",
                    side_effect=AssertionError(
                        "non-JSON approval YAML must not reach hashing"
                    ),
                ):
                    plan = archive_services.zet_revision_plan(
                        archive_root,
                        zettel_id=fixture["zettel_id"],
                        proposal_path=fixture["proposal_relative"],
                        dry_run=True,
                    )
                self.assertFalse(plan["ok"], plan)
                self.assertEqual(plan["status"], "blocked")
                self.assertIsNone(plan["canonical"]["sha256"])
                self.assertIsNone(plan["proposal"]["sha256"])
                self.assertIsNone(plan["plan_digest"])

    def test_zet_revision_plan_rejects_invalid_inputs_before_hash_or_plan_digest(self) -> None:
        for target in ("canonical", "proposal"):
            with self.subTest(target=target), tempfile.TemporaryDirectory() as tmp:
                archive_root = self.copy_fake_archive(Path(tmp) / "archive")
                fixture = self.create_zet_revision_proposal(archive_root)
                path = (
                    fixture["canonical_path"]
                    if target == "canonical"
                    else fixture["proposal_path"]
                )
                private_marker = f"PRIVATE_DUPLICATE_{target.upper()}_VALUE"
                text = path.read_text(encoding="utf-8")
                path.write_text(
                    text.replace(
                        "status: canonical",
                        f"status: canonical\nstatus: {private_marker}",
                        1,
                    ),
                    encoding="utf-8",
                )

                with patch.object(
                    archive_services.hashlib,
                    "sha256",
                    side_effect=AssertionError(
                        "rejected zettel bytes must not be fingerprinted"
                    ),
                ):
                    result = archive_services.zet_revision_plan(
                        archive_root,
                        zettel_id=fixture["zettel_id"],
                        proposal_path=fixture["proposal_relative"],
                        dry_run=True,
                    )

                self.assertEqual(result["status"], "blocked", result)
                self.assertIsNone(result["canonical"]["sha256"])
                self.assertIsNone(result["proposal"]["sha256"])
                self.assertIsNone(result["proposal"]["semantic_sha256"])
                self.assertIsNone(result["plan_digest"])
                self.assertNotIn(
                    private_marker, json.dumps(result, ensure_ascii=False)
                )

    def test_zet_revision_plan_binds_one_private_proposal_without_echoing_content(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            canonical_path = sorted((archive_root / "zettels").glob("*.md"))[0]
            frontmatter, body = archive_services.split_zettel_text(
                canonical_path.read_text(encoding="utf-8")
            )
            current_abstract = "Current reviewed first read for the canonical zet."
            frontmatter["abstract"] = current_abstract
            canonical_path.write_text(
                "---\n" + archive_cli.dump_yaml(frontmatter) + "---\n\n" + body.rstrip() + "\n",
                encoding="utf-8",
            )

            proposal_frontmatter = json.loads(json.dumps(frontmatter))
            abstract_marker = "PRIVATE_REVISION_ABSTRACT_MARKER"
            body_marker = "PRIVATE_REVISION_BODY_MARKER"
            proposal_frontmatter["abstract"] = abstract_marker
            proposal_relative = ".wom-scratch/revisions/private-filename-marker.md"
            proposal_path = archive_root / proposal_relative
            proposal_path.parent.mkdir(parents=True, exist_ok=True)
            proposal_path.write_text(
                "---\n"
                + archive_cli.dump_yaml(proposal_frontmatter)
                + "---\n\n"
                + body.rstrip()
                + f"\n\n{body_marker}\n",
                encoding="utf-8",
            )

            missing_code, missing_output = self.run_cli(
                [
                    "zet-revision-plan",
                    str(archive_root),
                    "--zettel-id",
                    frontmatter["id"],
                    "--proposal",
                    proposal_relative,
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(missing_code, 1)
            self.assertIn("requires --dry-run", missing_output)

            code, output = self.run_cli(
                [
                    "revise-zet-plan",
                    str(archive_root),
                    "--zettel-id",
                    frontmatter["id"],
                    "--proposal",
                    proposal_relative,
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(code, 0, output)
            result = json.loads(output)
            self.assertTrue(result["ok"])
            self.assertEqual(result["schema"], "wom-kit/zet-revision-plan/v0.1")
            self.assertEqual(result["status"], "ready_for_human_review")
            self.assertTrue(result["change_summary"]["body_changed"])
            self.assertTrue(result["change_summary"]["abstract_changed"])
            self.assertTrue(result["change_summary"]["semantic_change_present"])
            self.assertRegex(result["canonical"]["sha256"], r"^sha256:[0-9a-f]{64}$")
            self.assertRegex(result["proposal"]["sha256"], r"^sha256:[0-9a-f]{64}$")
            self.assertRegex(result["plan_digest"], r"^sha256:[0-9a-f]{64}$")
            self.assertTrue(result["approval_contract"]["approved_write_implemented"])
            self.assertFalse(result["write_boundary"]["files_written"])
            self.assertFalse(result["privacy_guards"]["zettel_id_echoed"])
            self.assertFalse(result["privacy_guards"]["abstract_text_echoed"])
            self.assertFalse(result["privacy_guards"]["body_text_echoed"])
            self.assertNotIn(frontmatter["id"], output)
            self.assertNotIn("private-filename-marker", output)
            self.assertNotIn(current_abstract, output)
            self.assertNotIn(abstract_marker, output)
            self.assertNotIn(body_marker, output)

    def test_zet_revision_plan_blocks_noop_system_field_abstract_and_locator_failures(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            canonical_path = sorted((archive_root / "zettels").glob("*.md"))[0]
            frontmatter, body = archive_services.split_zettel_text(
                canonical_path.read_text(encoding="utf-8")
            )
            frontmatter["abstract"] = "Reviewed current abstract."
            canonical_path.write_text(
                "---\n" + archive_cli.dump_yaml(frontmatter) + "---\n\n" + body.rstrip() + "\n",
                encoding="utf-8",
            )
            proposal_relative = ".wom-scratch/revisions/private-validation-cases.md"
            proposal_path = archive_root / proposal_relative
            proposal_path.parent.mkdir(parents=True, exist_ok=True)

            def run_case(
                proposed_frontmatter: dict[str, Any], proposed_body: str
            ) -> tuple[dict[str, Any], str]:
                proposal_path.write_text(
                    "---\n"
                    + archive_cli.dump_yaml(proposed_frontmatter)
                    + "---\n\n"
                    + proposed_body.rstrip()
                    + "\n",
                    encoding="utf-8",
                )
                code, output = self.run_cli(
                    [
                        "canonical-revision-plan",
                        str(archive_root),
                        "--zettel-id",
                        frontmatter["id"],
                        "--proposal",
                        proposal_relative,
                        "--dry-run",
                        "--format",
                        "json",
                    ]
                )
                self.assertEqual(code, 1, output)
                return json.loads(output), output

            noop, _noop_output = run_case(json.loads(json.dumps(frontmatter)), body)
            self.assertIn("proposal_has_no_semantic_revision", noop["blockers"])

            system_changed = json.loads(json.dumps(frontmatter))
            system_changed["created_at"] = "1999-01-01T00:00:00Z"
            system_result, _system_output = run_case(
                system_changed, body + "\nMeaningful body correction."
            )
            self.assertIn(
                "system_managed_field_changed:created_at", system_result["blockers"]
            )

            creator_changed = json.loads(json.dumps(frontmatter))
            creator_changed["provenance"]["created_by"] = "person:replacement"
            creator_result, _creator_output = run_case(
                creator_changed, body + "\nMeaningful body correction."
            )
            self.assertIn(
                "system_managed_provenance_field_changed:created_by",
                creator_result["blockers"],
            )

            missing_abstract = json.loads(json.dumps(frontmatter))
            missing_abstract.pop("abstract")
            abstract_result, _abstract_output = run_case(
                missing_abstract, body + "\nMeaningful body correction."
            )
            self.assertTrue(
                any(
                    blocker.startswith("proposal_explicit_abstract_not_ready:")
                    for blocker in abstract_result["blockers"]
                )
            )

            locator_marker = "D:\\private-source.txt"
            locator_result, locator_output = run_case(
                json.loads(json.dumps(frontmatter)), body + "\n" + locator_marker
            )
            self.assertIn("proposal_body_contains_private_locator", locator_result["blockers"])
            self.assertNotIn(locator_marker, locator_output)

            identity_changed = json.loads(json.dumps(frontmatter))
            identity_marker = "zet_private_replacement_identity"
            identity_changed["id"] = identity_marker
            identity_result, identity_output = run_case(
                identity_changed, body + "\nMeaningful body correction."
            )
            self.assertIn(
                "proposal_frontmatter_identity_mismatch", identity_result["blockers"]
            )
            self.assertNotIn(identity_marker, identity_output)

            unknown_edge = json.loads(json.dumps(frontmatter))
            unknown_edge["edges"] = [
                {"type": "private_unknown_edge_type", "target": frontmatter["id"]}
            ]
            edge_result, edge_output = run_case(
                unknown_edge, body + "\nMeaningful body correction."
            )
            self.assertIn(
                "proposal_allowed_edges_check_blocked", edge_result["blockers"]
            )
            self.assertNotIn("private_unknown_edge_type", edge_output)

