    def test_zet_catalog_strict_chain_blocks_skips_and_proves_contiguous_completion(self) -> None:
        archive_root = KIT_ROOT / "examples" / "fake-life-archive"
        first_code, first_output = self.run_cli(
            [
                "zet-catalog",
                str(archive_root),
                "--projection",
                "reading",
                "--coverage-mode",
                "strict",
                "--page-size",
                "1",
                "--dry-run",
                "--format",
                "json",
            ]
        )
        self.assertEqual(first_code, 0, first_output)
        first = json.loads(first_output)
        token = first["coverage"]["continuation_token"]
        self.assertTrue(token)
        self.assertTrue(first["coverage"]["contiguous_prefix_verified"])
        self.assertEqual(first["coverage"]["covered_count"], 1)
        self.assertFalse(first["coverage"]["archive_wide_coverage_claim_ready"])
        self.assertRegex(first["coverage"]["page_entry_identity_sha256"], r"^sha256:[0-9a-f]{64}$")
        self.assertTrue(first["continuation_contract"]["duplicate_ids_distinguished_in_chain"])
        self.assertFalse(first["continuation_contract"]["cryptographic_attestation"])
        self.assertFalse(first["continuation_contract"]["persistent_loop_state_created"])

        skipped_code, skipped_output = self.run_cli(
            [
                "zet-catalog",
                str(archive_root),
                "--projection",
                "reading",
                "--coverage-mode",
                "strict",
                "--cursor",
                "2",
                "--page-size",
                "1",
                "--continuation-token",
                token,
                "--dry-run",
                "--format",
                "json",
            ]
        )
        self.assertEqual(skipped_code, 1, skipped_output)
        self.assertIn("cursor does not match the prior page", skipped_output)

        tampered = token[:-1] + ("0" if token[-1] != "0" else "1")
        tampered_code, tampered_output = self.run_cli(
            [
                "zet-catalog",
                str(archive_root),
                "--projection",
                "reading",
                "--coverage-mode",
                "strict",
                "--cursor",
                "1",
                "--continuation-token",
                tampered,
                "--dry-run",
                "--format",
                "json",
            ]
        )
        self.assertEqual(tampered_code, 1, tampered_output)
        self.assertIn("checksum does not match", tampered_output)

        collected = [item["id"] for item in first["items"]]
        current = first
        while not current["coverage"]["complete"]:
            next_code, next_output = self.run_cli(
                [
                    "zet-catalog",
                    str(archive_root),
                    "--projection",
                    "reading",
                    "--coverage-mode",
                    "strict",
                    "--cursor",
                    str(current["coverage"]["next_cursor"]),
                    "--continuation-token",
                    current["coverage"]["continuation_token"],
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(next_code, 0, next_output)
            current = json.loads(next_output)
            collected.extend(item["id"] for item in current["items"])

        self.assertTrue(current["coverage"]["archive_wide_coverage_claim_ready"])
        self.assertFalse(current["coverage"]["archive_wide_abstract_reading_claim_ready"])
        self.assertTrue(current["coverage"]["archive_wide_followup_resolution_ready"])
        self.assertEqual(current["coverage"]["covered_count"], current["coverage"]["total_count"])
        self.assertIsNone(current["coverage"]["continuation_token"])
        self.assertEqual(len(collected), current["coverage"]["total_count"])
        self.assertEqual(len(set(collected)), current["coverage"]["total_count"])

    def test_zet_catalog_compact_continuation_omits_only_repeated_metadata(self) -> None:
        archive_root = KIT_ROOT / "examples" / "fake-life-archive"
        first_code, first_output = self.run_cli(
            [
                "zet-catalog",
                str(archive_root),
                "--projection",
                "reading",
                "--coverage-mode",
                "strict",
                "--page-size",
                "1",
                "--dry-run",
                "--format",
                "json",
            ]
        )
        self.assertEqual(first_code, 0, first_output)
        first = json.loads(first_output)
        self.assertEqual(first["response_profile"], "full")
        self.assertIn("order_evidence", first)

        continuation_args = [
            "zet-catalog",
            str(archive_root),
            "--projection",
            "reading",
            "--coverage-mode",
            "strict",
            "--cursor",
            str(first["coverage"]["next_cursor"]),
            "--page-size",
            "1",
            "--continuation-token",
            first["coverage"]["continuation_token"],
            "--dry-run",
            "--format",
            "json",
        ]
        full_code, full_output = self.run_cli(continuation_args)
        self.assertEqual(full_code, 0, full_output)
        full = json.loads(full_output)

        compact_code, compact_output = self.run_cli(
            [*continuation_args[:-3], "--response-profile", "continuation", *continuation_args[-3:]]
        )
        self.assertEqual(compact_code, 0, compact_output)
        compact = json.loads(compact_output)

        self.assertEqual(compact["schema"], "wom-kit/zet-catalog/v0.8")
        self.assertEqual(compact["response_profile"], "continuation")
        self.assertEqual(compact["items"], full["items"])
        self.assertEqual(compact["snapshot"], full["snapshot"])
        self.assertEqual(compact["coverage"], full["coverage"])
        self.assertEqual(compact["continuation_contract"], full["continuation_contract"])
        self.assertEqual(compact["session_consistency"], full["session_consistency"])
        self.assertEqual(compact["privacy_guards"], full["privacy_guards"])
        self.assertFalse(compact["privacy_guards"]["zettel_body_text_read"])
        for key in (
            "abstract_counts",
            "abstract_coverage",
            "identity_coverage",
            "order_evidence",
            "scan",
            "closed_actions",
        ):
            self.assertIn(key, full)
            self.assertNotIn(key, compact)
        self.assertIn("scope", full["workload_estimate"])
        self.assertNotIn("scope", compact["workload_estimate"])
        self.assertTrue(compact["workload_estimate"]["scope_omitted_in_continuation_profile"])
        contract = compact["response_profile_contract"]
        self.assertTrue(contract["first_page_full_required"])
        self.assertTrue(contract["items_unchanged"])
        self.assertTrue(contract["coverage_semantics_unchanged"])
        self.assertTrue(contract["snapshot_and_token_retained"])
        self.assertEqual(
            contract["omitted_repeated_sections"],
            [
                "abstract_counts",
                "abstract_coverage",
                "identity_coverage",
                "order_evidence",
                "scan",
                "closed_actions",
                "workload_estimate.scope",
            ],
        )
        self.assertLess(
            compact["workload_estimate"]["response"]["estimated_service_result_json_tokens"],
            full["workload_estimate"]["response"]["estimated_service_result_json_tokens"],
        )

        invalid_code, invalid_output = self.run_cli(
            [
                "zet-catalog",
                str(archive_root),
                "--projection",
                "reading",
                "--coverage-mode",
                "strict",
                "--response-profile",
                "continuation",
                "--dry-run",
                "--format",
                "json",
            ]
        )
        self.assertEqual(invalid_code, 1, invalid_output)
        self.assertIn("requires a nonzero strict continuation cursor", invalid_output)

