    def test_zet_catalog_pass_scans_frontmatter_once_and_publishes_complete_private_jsonl(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            zettel_paths = sorted((archive_root / "zettels").glob("*.md"))
            self.assertGreater(len(zettel_paths), 1)
            private_body_marker = "PRIVATE_CATALOG_PASS_BODY_MUST_NOT_APPEAR"
            zettel_paths[0].write_text(
                zettel_paths[0].read_text(encoding="utf-8") + f"\n{private_body_marker}\n",
                encoding="utf-8",
            )
            output_relative = ".wom-scratch/diagnostics/catalog-pass.jsonl"
            output_path = archive_root / output_relative
            output_path.parent.mkdir(parents=True, exist_ok=True)
            preexisting_partial = output_path.parent / ".catalog-pass.jsonl.prior.partial"
            preexisting_partial_bytes = b"PRIVATE PRIOR PARTIAL MUST STAY UNREAD\n"
            preexisting_partial.write_bytes(preexisting_partial_bytes)

            real_catalog_item = archive_services.zet_catalog_item
            with patch.object(archive_services, "zet_catalog_item", wraps=real_catalog_item) as catalog_item:
                code, stdout, stderr = self.run_cli_split(
                    [
                        "zet-catalog-pass",
                        str(archive_root),
                        "--projection",
                        "reading",
                        "--page-size",
                        "1",
                        "--output",
                        output_relative,
                        "--dry-run",
                        "--progress",
                        "--format",
                        "json",
                    ]
                )

            self.assertEqual(code, 0, stdout + stderr)
            summary = json.loads(stdout)
            self.assertTrue(summary["ok"], summary)
            self.assertEqual(summary["status"], "complete")
            self.assertEqual(summary["page_count"], len(zettel_paths))
            self.assertEqual(summary["coverage"]["covered_count"], len(zettel_paths))
            self.assertTrue(summary["coverage"]["archive_wide_coverage_claim_ready"])
            self.assertEqual(summary["session"]["initial_frontmatter_files_scanned"], len(zettel_paths))
            self.assertTrue(summary["session"]["completion_revalidation_performed"])
            self.assertFalse(summary["session"]["cache_persisted"])
            self.assertFalse(summary["session"]["mcp_cache_used"])
            self.assertEqual(summary["output"]["preexisting_partial_count"], 1)
            self.assertFalse(summary["output"]["preexisting_partials_read"])
            self.assertFalse(summary["output"]["preexisting_partials_deleted"])
            self.assertEqual(catalog_item.call_count, len(zettel_paths))
            self.assertNotIn("items", summary)
            self.assertNotIn(private_body_marker, stdout + stderr)
            self.assertNotIn("PRIVATE PRIOR PARTIAL MUST STAY UNREAD", stdout + stderr)
            self.assertNotIn(str(archive_root), stdout + stderr)
            self.assertIn("catalog-path-metadata", stderr)
            self.assertIn("catalog-session-snapshot", stderr)
            self.assertIn("catalog-page", stderr)

            self.assertTrue(output_path.is_file())
            records = [json.loads(line) for line in output_path.read_text(encoding="utf-8").splitlines()]
            self.assertEqual(summary["output"]["bytes_written"], output_path.stat().st_size)
            self.assertEqual(summary["output"]["line_count"], len(records))
            self.assertEqual(records[0]["record_type"], "catalog_pass_header")
            self.assertEqual(records[-1]["record_type"], "catalog_pass_footer")
            page_records = [record for record in records if record.get("record_type") == "catalog_page"]
            self.assertEqual(len(page_records), len(zettel_paths))
            self.assertEqual(page_records[0]["result"]["response_profile"], "full")
            self.assertTrue(
                all(record["result"]["response_profile"] == "continuation" for record in page_records[1:])
            )
            collected = [
                item["id"]
                for record in page_records
                for item in record["result"].get("items", [])
            ]
            self.assertEqual(len(collected), len(zettel_paths))
            self.assertEqual(len(set(collected)), len(zettel_paths))
            self.assertTrue(records[-1]["coverage"]["archive_wide_coverage_claim_ready"])
            self.assertTrue(records[-1]["session_consistency"]["completion_revalidation_performed"])
            self.assertNotIn(private_body_marker, output_path.read_text(encoding="utf-8"))
            self.assertEqual(preexisting_partial.read_bytes(), preexisting_partial_bytes)
            self.assertEqual(list(output_path.parent.glob(".*.partial")), [preexisting_partial])

    def test_zet_catalog_pass_read_validates_whole_artifact_before_returning_one_page(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            output_relative = ".wom-scratch/diagnostics/catalog-pass-read.jsonl"
            pass_code, pass_stdout, pass_stderr = self.run_cli_split(
                [
                    "zet-catalog-pass",
                    str(archive_root),
                    "--projection",
                    "reading",
                    "--page-size",
                    "1",
                    "--output",
                    output_relative,
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(pass_code, 0, pass_stdout + pass_stderr)
            pass_summary = json.loads(pass_stdout)
            expected_sha256 = pass_summary["output"]["sha256"]
            output_path = archive_root / output_relative
            self.assertEqual(expected_sha256, "sha256:" + hashlib.sha256(output_path.read_bytes()).hexdigest())

            summary_code, summary_stdout, summary_stderr = self.run_cli_split(
                [
                    "zet-catalog-pass-read",
                    str(archive_root),
                    "--input",
                    output_relative,
                    "--expected-sha256",
                    expected_sha256,
                    "--dry-run",
                    "--progress",
                ]
            )
            self.assertEqual(summary_code, 0, summary_stdout + summary_stderr)
            summary = json.loads(summary_stdout)
            self.assertTrue(summary["ok"], summary)
            self.assertEqual(summary["status"], "complete_validated")
            self.assertTrue(summary["artifact"]["structurally_complete"])
            self.assertTrue(summary["artifact"]["expected_sha256_matches"])
            self.assertIsNone(summary["selected_page"])
            self.assertEqual(summary["selection"]["selected_page_count"], 0)
            self.assertTrue(summary["inspection"]["archive_wide_coverage_claim_ready"])
            self.assertNotIn(str(archive_root), summary_stdout + summary_stderr)
            self.assertIn("catalog-pass-artifact", summary_stderr)

            page_code, page_stdout = self.run_cli(
                [
                    "catalog-pass-read",
                    str(archive_root),
                    "--input",
                    output_relative,
                    "--page-index",
                    "0",
                    "--expected-sha256",
                    expected_sha256,
                    "--dry-run",
                ]
            )
            self.assertEqual(page_code, 0, page_stdout)
            page = json.loads(page_stdout)
            self.assertEqual(page["status"], "page_ready")
            self.assertEqual(page["selected_page"]["record_type"], "catalog_page")
            self.assertEqual(page["selected_page"]["page_index"], 0)
            self.assertEqual(len(page["selected_page"]["result"]["items"]), 1)
            self.assertEqual(page["selection"]["selected_page_count"], 1)
            self.assertFalse(page["selection"]["whole_artifact_loaded_into_output"])

            unbound_code, unbound_stdout = self.run_cli(
                [
                    "zet-catalog-pass-read",
                    str(archive_root),
                    "--input",
                    output_relative,
                    "--page-index",
                    "0",
                    "--dry-run",
                ]
            )
            self.assertEqual(unbound_code, 1, unbound_stdout)
            unbound = json.loads(unbound_stdout)
            self.assertTrue(unbound["artifact"]["structurally_complete"])
            self.assertIsNone(unbound["selected_page"])

            missing_code, missing_stdout = self.run_cli(
                [
                    "zet-catalog-pass-read",
                    str(archive_root),
                    "--input",
                    output_relative,
                    "--page-index",
                    str(summary["inspection"]["page_count"]),
                    "--expected-sha256",
                    expected_sha256,
                    "--dry-run",
                ]
            )
            self.assertEqual(missing_code, 1, missing_stdout)
            missing = json.loads(missing_stdout)
            self.assertFalse(missing["ok"])
            self.assertIsNone(missing["selected_page"])

            private_tamper_marker = "PRIVATE_TAMPERED_CATALOG_VALUE"
            tampered_records = [json.loads(line) for line in output_path.read_text(encoding="utf-8").splitlines()]
            tampered_records[1]["result"]["body"] = private_tamper_marker
            output_path.write_text(
                "".join(
                    json.dumps(record, ensure_ascii=False, separators=(",", ":")) + "\n"
                    for record in tampered_records
                ),
                encoding="utf-8",
            )
            tampered_sha256 = "sha256:" + hashlib.sha256(output_path.read_bytes()).hexdigest()
            tampered_code, tampered_stdout = self.run_cli(
                [
                    "zet-catalog-pass-read",
                    str(archive_root),
                    "--input",
                    output_relative,
                    "--page-index",
                    "0",
                    "--expected-sha256",
                    tampered_sha256,
                    "--dry-run",
                ]
            )
            self.assertEqual(tampered_code, 1, tampered_stdout)
            tampered = json.loads(tampered_stdout)
            self.assertFalse(tampered["ok"])
            self.assertIsNone(tampered["selected_page"])
            self.assertTrue(tampered["artifact"]["expected_sha256_matches"])
            self.assertFalse(tampered["artifact"]["structurally_complete"])
            self.assertNotIn(private_tamper_marker, tampered_stdout)

