    def test_activity_group_membership_recovery_plan_detects_historical_drift_but_recover_fails_closed(
        self,
    ) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = Path(tmp) / "personal-archive"
            fixture = self.create_activity_group_write_fixture(
                archive_root,
                archive_id="archive:personal:activity-group-recovery-drift",
                suffix="60",
            )
            historical = self.install_historical_activity_group_transaction_fixture(
                archive_root, fixture, state="partial"
            )
            valid_plan = archive_services.activity_group_membership_recovery_plan(
                archive_root,
                expected_request_sha256=fixture["request_sha256"],
                dry_run=True,
            )
            self.assertTrue(valid_plan["ok"], valid_plan)
            guard_path = (
                archive_root
                / ".wom-scratch"
                / "private"
                / "activity-groups"
                / archive_services.ACTIVITY_GROUP_MEMBERSHIP_RECOVERY_GUARD_NAME
            )
            guard_path.write_text(
                "PRIVATE_CONCURRENT_RECOVERY_GUARD", encoding="utf-8"
            )
            before_guarded = self.snapshot_archive_files(archive_root)
            guarded = archive_services.activity_group_membership_recover(
                archive_root,
                expected_request_sha256=fixture["request_sha256"],
                expected_recovery_plan_sha256=valid_plan[
                    "recovery_plan_sha256"
                ],
                approve=True,
                reviewed_by="person:activity-group-reviewer",
                affirm_recovery_reviewed=True,
            )
            self.assert_compound_revision_write_blocked(
                guarded,
                lifecycle_action="activity_group_membership_recover",
            )
            self.assertEqual(
                self.snapshot_archive_files(archive_root), before_guarded
            )
            guard_path.unlink()

            drift_path = historical["candidates"][-1]["path"]
            drift_bytes = drift_path.read_bytes() + (
                b"\nPRIVATE_UNKNOWN_EXTERNAL_DRIFT\n"
            )
            drift_path.write_bytes(drift_bytes)
            forensic = archive_services.activity_group_membership_recovery_plan(
                archive_root,
                expected_request_sha256=fixture["request_sha256"],
                dry_run=True,
            )
            self.assertFalse(forensic["ok"])
            self.assertEqual(forensic["transaction_state"], "unknown_or_drifted")
            self.assertEqual(forensic["recovery_action"], "manual_forensic_hold")
            self.assertIn(
                "activity_group_recovery_manual_forensic_hold",
                forensic["blockers"],
            )
            before_forensic = self.snapshot_archive_files(archive_root)
            blocked = archive_services.activity_group_membership_recover(
                archive_root,
                expected_request_sha256=fixture["request_sha256"],
                expected_recovery_plan_sha256=forensic[
                    "recovery_plan_sha256"
                ],
                approve=True,
                reviewed_by="person:activity-group-reviewer",
                affirm_recovery_reviewed=True,
            )
            self.assert_compound_revision_write_blocked(
                blocked,
                lifecycle_action="activity_group_membership_recover",
            )
            self.assertEqual(
                self.snapshot_archive_files(archive_root), before_forensic
            )
            self.assertEqual(drift_path.read_bytes(), drift_bytes)

