    def test_activity_group_membership_plan_enforces_byte_and_member_bounds(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = Path(tmp) / "personal-archive"
            archive_id = "archive:personal:activity-group-bounds"
            init_code, init_output = self.init_personal_archive(
                archive_root,
                archive_id,
            )
            self.assertEqual(init_code, 0, init_output)
            anchor_id = "zet_20260729_023000_private_bound_anchor"
            member_id = "zet_20260729_023001_private_bound_member"
            self.create_activity_group_canonical(
                archive_root,
                zettel_id=anchor_id,
                title="PRIVATE_BOUND_ANCHOR_TITLE",
                facets={
                    "record_type": "event",
                    "event_start": "2022-08-26",
                },
            )
            self.create_activity_group_canonical(
                archive_root,
                zettel_id=member_id,
                title="PRIVATE_BOUND_MEMBER_TITLE",
                body="PRIVATE_BOUND_MEMBER_BODY_" + ("x" * 512),
            )
            request_relative = (
                ".wom-scratch/private/activity-groups/private-bounds.json"
            )
            request_path = archive_root / request_relative
            request_path.parent.mkdir(parents=True, exist_ok=True)
            request_doc = {
                "schema": (
                    "wom-kit/activity-group-membership-request/v0.1"
                ),
                "archive_id": archive_id,
                "anchor_zettel_id": anchor_id,
                "member_zettel_ids": [member_id],
            }
            request_path.write_text(
                json.dumps(request_doc),
                encoding="utf-8",
            )
            anchor_bytes = (
                archive_root / "zettels" / f"{anchor_id}.md"
            ).read_bytes()
            member_bytes = (
                archive_root / "zettels" / f"{member_id}.md"
            ).read_bytes()

            with patch.object(
                archive_services,
                "ACTIVITY_GROUP_MEMBERSHIP_MAX_TOTAL_CANONICAL_BYTES",
                len(anchor_bytes) + len(member_bytes) - 1,
            ):
                total_bound = (
                    archive_services.activity_group_membership_plan(
                        archive_root,
                        request_path=request_relative,
                        dry_run=True,
                    )
                )
            self.assertFalse(total_bound["ok"])
            self.assertIn(
                "canonical_target_exceeds_remaining_total_budget",
                total_bound["items"][0]["blocker_codes"],
            )
            self.assertNotIn(
                member_id,
                json.dumps(total_bound, ensure_ascii=False),
            )

            with self.assertRaisesRegex(
                archive_services.ArchiveServiceError,
                "^canonical_target_exceeds_remaining_total_budget$",
            ):
                archive_services._read_activity_group_canonical_bytes(
                    archive_root / "zettels" / f"{member_id}.md",
                    max_bytes=len(member_bytes) - 1,
                )

            oversized_payload = {
                **request_doc,
                "padding": "PRIVATE_BOUND_REQUEST_PADDING",
            }
            request_path.write_text(
                json.dumps(oversized_payload),
                encoding="utf-8",
            )
            with patch.object(
                archive_services,
                "ACTIVITY_GROUP_MEMBERSHIP_MAX_REQUEST_BYTES",
                64,
            ):
                request_bound = (
                    archive_services.activity_group_membership_plan(
                        archive_root,
                        request_path=request_relative,
                        dry_run=True,
                    )
                )
            self.assertFalse(request_bound["ok"])
            self.assertIn(
                "request_file_exceeds_2_mib",
                request_bound["blockers"],
            )
            self.assertNotIn(
                "PRIVATE_BOUND_REQUEST_PADDING",
                json.dumps(request_bound, ensure_ascii=False),
            )

            request_path.write_text(
                json.dumps(request_doc),
                encoding="utf-8",
            )
            member_bound = archive_services.activity_group_membership_plan(
                archive_root,
                request_path=request_relative,
                dry_run=True,
                max_members=0,
            )
            self.assertFalse(member_bound["ok"])
            self.assertIn(
                "max_members_out_of_range",
                member_bound["blockers"],
            )
            self.assertEqual(member_bound["items"], [])

            standard_member_path = (
                archive_root / "zettels" / f"{member_id}.md"
            )
            nonstandard_member_path = (
                archive_root / "zettels" / "legacy-private-member-name.md"
            )
            standard_member_path.rename(nonstandard_member_path)
            nonstandard_before = nonstandard_member_path.read_bytes()
            standard_path_required = (
                archive_services.activity_group_membership_plan(
                    archive_root,
                    request_path=request_relative,
                    dry_run=True,
                )
            )
            self.assertFalse(standard_path_required["ok"])
            self.assertIn(
                "requested_zettel_missing_standard_canonical_path",
                standard_path_required["items"][0]["blocker_codes"],
            )
            self.assertEqual(
                nonstandard_before,
                nonstandard_member_path.read_bytes(),
            )
            serialized = json.dumps(
                standard_path_required,
                ensure_ascii=False,
            )
            self.assertNotIn(member_id, serialized)
            self.assertNotIn(nonstandard_member_path.name, serialized)

    def test_doctor_aggregates_possible_inbox_pipeline_bypass_signal(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = Path(tmp) / "personal-archive"
            init_code, init_output = self.init_personal_archive(
                archive_root,
                "archive:personal:inbox-pipeline-doctor",
            )
            self.assertEqual(init_code, 0, init_output)
            private_path = self.create_inbox_pipeline_audit_draft(
                archive_root,
                draft_id="zet_20260729_010206_private_doctor",
                title="PRIVATE_DOCTOR_TITLE",
                promotion_stage="draft",
                legacy_draft_suffix=True,
            )

            diagnostics = archive_cli.Doctor(archive_root).run()
            signals = [
                item
                for item in diagnostics
                if item.code == "possible_out_of_pipeline_inbox_draft"
            ]
            self.assertEqual(len(signals), 1)
            self.assertEqual(signals[0].severity, "WARN")
            self.assertIn("not proof", signals[0].message)
            self.assertNotIn(private_path.name, signals[0].message)

            code, output = self.run_cli(
                [
                    "doctor",
                    str(archive_root),
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(code, 0, output)
            self.assertIn(
                "possible_out_of_pipeline_inbox_draft",
                output,
            )
            self.assertNotIn("PRIVATE_DOCTOR_TITLE", output)
            self.assertNotIn(private_path.name, output)

            strict_code, strict_output = self.run_cli(
                [
                    "doctor",
                    str(archive_root),
                    "--strict",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(strict_code, 1, strict_output)
            self.assertIn(
                "possible_out_of_pipeline_inbox_draft",
                strict_output,
            )

