            real_code, real_output = self.run_cli(
                [
                    "mint-zet",
                    str(archive_root),
                    "--path",
                    "inbox/zet_20260519_draft_ai_lunch_note.md",
                    "--approve",
                    "--reviewed-by",
                    "person:test",
                    "--affirm",
                    "legacy_source_fidelity_reviewed",
                    "--format",
                    "json",
                ]
            )
