    def test_retire_draft_batch_reuses_edge_receipt_index_for_edge_evolved_targets(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self.copy_fake_archive(Path(tmp) / "archive")
            first_id = "zet_20260620_batch_retire_edge_alpha"
            second_id = "zet_20260620_batch_retire_edge_beta"
            for zettel_id, title, body in (
                (
                    first_id,
                    "Batch retire edge alpha",
                    "Batch retire edge alpha body with enough distinct material for duplicate scanning.\n",
                ),
                (
                    second_id,
                    "Batch retire edge beta",
                    "Batch retire edge beta body with a separate thought and enough distinct content.\n",
                ),
            ):
                draft_path = self.make_batch_ready_draft(archive_root, zettel_id, title, body)
                mint_code, mint_output = self.run_cli(
                    [
                        "mint-zet",
                        str(archive_root),
                        "--path",
                        archive_cli.archive_relative_path(draft_path, archive_root),
                        "--approve",
                        "--reviewed-by",
                        "person:test",
                        "--format",
                        "json",
                    ]
                )
                self.assertEqual(mint_code, 0, mint_output)
                edge_code, edge_output = self.run_cli(
                    [
                        "zettel-edge",
                        str(archive_root),
                        "--from-zettel",
                        zettel_id,
                        "--target",
                        "zet_20240505_fake_company_onboarding_insight",
                        "--edge-type",
                        "semantic",
                        "--visibility",
                        "private",
                        "--approve",
                        "--reviewed-by",
                        "person:test",
                        "--format",
                        "json",
                    ]
                )
                self.assertEqual(edge_code, 0, edge_output)

            self.assertTrue(archive_services.index_archive(archive_root)["index_complete"])
            retire_plan_path = archive_root / "workbench" / "retire-edge-batch.plan.json"
            retire_plan_path.write_text(
                json.dumps(
                    {
                        "schema": "wom-kit/retire-draft-batch/v0.1",
                        "policy": {"policy_id": "policy:fixture-batch-retire-edge"},
                        "items": [{"zettel_id": first_id}, {"zettel_id": second_id}],
                    },
                    indent=2,
                ),
                encoding="utf-8",
            )
            original_edge_index = archive_services.edge_receipts_by_source
            edge_index_calls: list[Path] = []

            def counted_edge_index(root: Path, **kwargs: Any) -> dict[str, list[dict[str, Any]]]:
                edge_index_calls.append(Path(root))
                return original_edge_index(root, **kwargs)

            before = self.archive_tree_snapshot(archive_root)
            with patch.object(
                archive_services,
                "edge_receipts_by_source",
                side_effect=counted_edge_index,
            ), patch.object(
                archive_services,
                "edge_receipts_for_source",
                side_effect=AssertionError(
                    "retire-draft-batch should not scan edge receipts per item"
                ),
            ):
                dry_code, dry_output = self.run_cli(
                    [
                        "retire-draft-batch",
                        str(archive_root),
                        "--plan",
                        "workbench/retire-edge-batch.plan.json",
                        "--dry-run",
                        "--format",
                        "json",
                    ]
                )
            self.assertEqual(dry_code, 0, dry_output)
            self.assertEqual(len(edge_index_calls), 1)
            result = json.loads(dry_output)
            self.assertEqual(result["summary"]["would_write_count"], 2)
            self.assertEqual(result["summary"]["written_item_count"], 0)
            for item in result["items"]:
                self.assertTrue(
                    any("approved zettel-edge receipts" in warning for warning in item["warnings"]),
                    item,
                )
            self.assertEqual(self.archive_tree_snapshot(archive_root), before)

