            self.assertFalse(validate_result["scope"]["index_cache_used"])
            scope_blocker = next(
                item
                for item in validate_result["diagnostics"]
                if item["code"] == "validate_scope_blocked"
            )
            self.assertIn("archive_index_incomplete", scope_blocker["message"])

