    def test_migrate_frontmatter_v03_dry_run_and_approve_are_idempotent(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = Path(tmp) / "personal-archive"
            init_code, init_output = self.init_personal_archive(
                archive_root,
                "archive:personal:migrate-test",
            )
            self.assertEqual(init_code, 0, init_output)
            zettel_path = archive_root / "inbox" / "zet_20260607_legacy_frontmatter.md"
            legacy_frontmatter = {
                "id": "zet_20260607_legacy_frontmatter",
                "title": "Legacy frontmatter",
                "created_at": "2026-06-07T10:00:00+09:00",
                "updated_at": "2026-06-07T10:00:00+09:00",
                "archive_id": "archive:personal:migrate-test",
                "status": "draft",
                "kind": "fleeting_capture",
                "provenance": {
                    "created_by": "person:test",
                    "source": "manual note",
                },
                "visibility": {"scope": "private"},
            }
            zettel_path.write_text(
                "---\n"
                + archive_cli.dump_yaml(legacy_frontmatter)
                + "---\n\nLegacy body.\n",
                encoding="utf-8",
            )
            original_text = zettel_path.read_text(encoding="utf-8")
            dry_code, dry_output = self.run_cli(
                [
                    "migrate",
                    str(archive_root),
                    "--target",
                    "frontmatter-v0.3",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(dry_code, 0, dry_output)
            dry_result = json.loads(dry_output)
            self.assertTrue(dry_result["dry_run"])
            self.assertEqual(dry_result["files_with_changes"], 1)
            self.assertEqual(dry_result["files_written"], [])
            self.assertEqual(zettel_path.read_text(encoding="utf-8"), original_text)
            before = self.archive_tree_snapshot(archive_root)
            approve_code, approve_output = self.run_cli(
                [
                    "migrate",
                    str(archive_root),
                    "--target",
                    "frontmatter-v0.3",
                    "--approve",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(approve_code, 1, approve_output)
            approve_result = json.loads(approve_output)
            self.assertEqual(approve_result["state"], "blocked")
            self.assertEqual(approve_result["lifecycle_action"], "migrate_archive")
            self.assertEqual(
                approve_result["reason_codes"],
                ["compound_exact_human_approval_binding_required"],
            )
            self.assertFalse(approve_result["private_values_echoed"])
            self.assertEqual(self.archive_tree_snapshot(archive_root), before)
            self.assertEqual(zettel_path.read_text(encoding="utf-8"), original_text)
            revert_code, revert_output = self.run_cli(
                [
                    "migrate",
                    str(archive_root),
                    "--target",
                    "frontmatter-v0.3",
                    "--revert",
                    "--dry-run",
                    "--format",
                    "json",
                ]
            )
            self.assertEqual(revert_code, 1, revert_output)
            self.assertIn(
                "snapshot_receipt_required",
                json.dumps(json.loads(revert_output), ensure_ascii=False),
            )

