    def _captured_sandbox(self, tmp: str) -> tuple[Path, str, str]:
        archive_root, selection, digest = self._simple_capture_setup(tmp)
        # Bounded pre-v0.4 history fixture.  Public capture approval is now fixed
        # closed, but staged-cleanup remains a read-only verifier of already
        # durable v0.2/v0.3 evidence.  Build exactly one historical object,
        # manifest row, and completed receipt without calling the dormant writer.
        staged_bytes = (archive_root / "staging" / "incoming" / "note.txt").read_bytes()
        self.assertEqual(hashlib.sha256(staged_bytes).hexdigest(), digest)
        logical_key = f"objects/sha256/{digest[:2]}/{digest}"
        object_path = archive_root.joinpath(*logical_key.split("/"))
        object_path.parent.mkdir(parents=True, exist_ok=True)
        object_path.write_bytes(staged_bytes)

        manifest_path = archive_root / "objects" / "manifests" / "files.jsonl"
        manifest_path.parent.mkdir(parents=True, exist_ok=True)
        manifest_record = {
            "object_id": f"sha256:{digest}",
            "sha256": digest,
            "logical_key": logical_key,
            "mime": "text/plain",
            "size_bytes": len(staged_bytes),
            "locations": [
                {
                    "provider": "local",
                    "path": logical_key,
                    "availability": "available",
                }
            ],
            "provenance": {
                "created_in": "archive:"
                + archive_services.read_archive_id(archive_root),
                "source": "b4_local_objet_capture",
                "captured_at": "2026-07-03T00:00:00Z",
                "captured_by": "person:test",
                "original_filename": "note.txt",
                "source_staged_path": "staging/incoming/note.txt",
            },
        }
        manifest_path.write_text(
            json.dumps(manifest_record, sort_keys=True, separators=(",", ":")) + "\n",
            encoding="utf-8",
        )

        captured_at = "2026-07-03T00:00:00Z"
        receipt_name = "20260703T000000Z-000000000001.json"
        item = {
            "item_id": "item",
            "approved_object_id": f"sha256:{digest}",
            "object_id": f"sha256:{digest}",
            "logical_key": logical_key,
            "size_bytes": len(staged_bytes),
            "mime": "text/plain",
            "planned_action": "capture",
            "action": "captured",
            "stored_sha256_verified": True,
            "manifest_record_appended": True,
            "blockers": [],
            "warnings": [],
        }
        receipt = {
            "receipt_id": f"receipt:objet-capture:{receipt_name[:-5]}",
            "schema": "wom-kit/objet-capture-receipt/v0.2",
            "dry_run": False,
            "ok": True,
            "aborted": False,
            "archive_id": archive_services.read_archive_id(archive_root),
            "selection_manifest_id": "approved:local-objet-capture:test",
            "selection_manifest_sha256": "sha256:"
            + hashlib.sha256(selection.read_bytes()).hexdigest(),
            "project_intake_context": None,
            "reviewed_by": "person:test",
            "captured_at": captured_at,
            "items": [item],
            "summary": archive_services.objet_capture_summary([item], approve=True),
            "blockers": [],
            "warnings": [],
        }
        receipt_path = archive_root / archive_services.OBJET_CAPTURE_RECEIPTS_DIR / receipt_name
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        receipt_path.write_text(
            json.dumps(receipt, indent=2, ensure_ascii=False) + "\n",
            encoding="utf-8",
        )
        return archive_root, digest, "staging/incoming"

    def test_staged_cleanup_check_all_captured_is_safe(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root, digest, staged = self._captured_sandbox(tmp)
            secret = "PRIVATE_REDACTED_CLEANUP_REF_9912"
            (archive_root / "zettels" / "zet_redacted_cleanup_probe.md").write_text(
                "---\n"
                "id: zet_redacted_cleanup_probe\n"
                "status: redacted\n"
                f"title: {secret}\n"
                "source_refs:\n"
                "  - type: object_id\n"
                f"    value: sha256:{digest}\n"
                "---\n"
                f"Body {secret}\n",
                encoding="utf-8",
            )
            result = archive_services.staged_cleanup_check(archive_root, staged)
            self.assertTrue(result["ok"], result)
            self.assertTrue(result["safe_to_cleanup"])
            self.assertFalse(result["deletion_performed"])
            entry = result["files"][0]
            self.assertEqual(entry["status"], "preserved")
            self.assertTrue(entry["preserved_bytes_verified"])
            self.assertTrue(entry["manifest_record_present"])
            self.assertEqual(entry["referencing_zets"], 0)
            self.assertNotIn(secret, json.dumps(result))

    def test_staged_cleanup_check_progress_is_content_free(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root, digest, staged = self._captured_sandbox(tmp)
            events: list[tuple[str, str, int | None, int | None]] = []
            result = archive_services.staged_cleanup_check(
                archive_root,
                staged,
                progress_callback=lambda stage, message, current, total: events.append(
                    (stage, message, current, total)
                ),
            )
            self.assertTrue(result["safe_to_cleanup"], result)
            stages = {stage for stage, _message, _current, _total in events}
            self.assertIn("manifest", stages)
            self.assertIn("staged-walk", stages)
            self.assertIn("verify", stages)
            rendered = json.dumps(events)
            self.assertNotIn("note.txt", rendered)
            self.assertNotIn(digest, rendered)

