    def test_derive_text_capture_blocks_missing_source_and_cli_gates(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self._sandbox(tmp, "archive:personal:derived-gates")
            text_file = Path(tmp) / "derived.txt"
            text_file.write_text("Derived text without a source object.\n", encoding="utf-8")
            missing_source = "sha256:" + "b" * 64

            result = archive_services.derived_text_capture_dry_run(
                archive_root,
                text_file=text_file,
                source_object_id=missing_source,
                derivation_kind="parser",
                tool_name="fake-parser",
                tool_version="1.0.0",
                review_status="unreviewed",
            )
            self.assertFalse(result["ok"])
            self.assertIn("source_object_missing", result["blockers"])

            base = [
                "derive-text",
                "capture",
                str(archive_root),
                "--text-file",
                str(text_file),
                "--source-object-id",
                missing_source,
                "--derivation-kind",
                "parser",
                "--tool-name",
                "fake-parser",
                "--tool-version",
                "1.0.0",
                "--review-status",
                "unreviewed",
            ]
            before = self._inventory(archive_root)
            code, output = self.run_cli(base)
            self.assertEqual(code, 1, output)
            code, output = self.run_cli(base + ["--dry-run", "--approve"])
            self.assertEqual(code, 1, output)
            code, output = self.run_cli(base + ["--approve", "--format", "json"])
            self.assertEqual(code, 1, output)
            blocked = json.loads(output)
            self.assertEqual(blocked["state"], "blocked")
            self.assertEqual(blocked["lifecycle_action"], "derived_text_capture_apply")
            self.assertEqual(
                blocked["reason_codes"],
                ["compound_exact_human_approval_binding_required"],
            )
            self.assertFalse(blocked["private_values_echoed"])
            self.assertEqual(self._inventory(archive_root), before)

    def test_derive_text_coverage_gate_finds_uncovered_textual_objets_without_paths(self) -> None:
        with tempfile.TemporaryDirectory() as tmp:
            archive_root = self._sandbox(tmp, "archive:personal:derived-coverage")
            covered_pdf = self._derived_text_source_object(archive_root, b"covered pdf bytes")
            docx_digest = hashlib.sha256(b"missing docx bytes").hexdigest()
            encrypted_digest = hashlib.sha256(b"encrypted pdf bytes").hexdigest()
            prehashed_text_digest = hashlib.sha256(b"prehashed unknown text bytes").hexdigest()
            manifest = archive_root / "objects" / "manifests" / "files.jsonl"
            with manifest.open("a", encoding="utf-8", newline="\n") as handle:
                handle.write(
                    json.dumps(
                        {
                            "object_id": f"sha256:{docx_digest}",
                            "sha256": docx_digest,
                            "logical_key": "objects/sample/private-client-contract.docx",
                            "mime": "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                            "size_bytes": 12345,
                            "locations": [],
                        },
                        separators=(",", ":"),
                    )
                    + "\n"
                )
                handle.write(
                    json.dumps(
                        {
                            "object_id": f"sha256:{encrypted_digest}",
                            "sha256": encrypted_digest,
                            "logical_key": "objects/sample/password-needed.pdf",
                            "mime": "application/pdf",
                            "size_bytes": 54321,
                            "locations": [],
                            "metadata": {"password_required": True},
                        },
                        separators=(",", ":"),
                    )
                    + "\n"
                )
                handle.write(
                    json.dumps(
                        {
                            "object_id": f"sha256:{prehashed_text_digest}",
                            "sha256": prehashed_text_digest,
                            "logical_key": f"objects/external/prehashed/notion_source_export/{prehashed_text_digest[:2]}/{prehashed_text_digest}",
                            "mime": "application/octet-stream",
                            "size_bytes": 222,
                            "locations": [{"provider": "external_prehashed", "store_ref": "notion-export-20260616"}],
                        },
                        separators=(",", ":"),
                    )
                    + "\n"
                )
            derived_manifest = archive_root / archive_services.DERIVED_TEXT_MANIFEST_RELATIVE_PATH
            derived_manifest.parent.mkdir(parents=True, exist_ok=True)
            derived_manifest.write_text(
                "\n".join(
                    [
                        json.dumps(
                            {
                                "derived_text_id": "derived-text:sha256:" + "1" * 64,
                                "source_object_id": covered_pdf,
                            },
                            separators=(",", ":"),
                        ),
                        json.dumps(
                            {
                                "derived_text_id": "derived-text:sha256:" + "2" * 64,
                                "source_object_id": f"sha256:{prehashed_text_digest}",
                            },
                            separators=(",", ":"),
                        ),
                    ]
                )
                + "\n",
                encoding="utf-8",
            )
            before = self._inventory(archive_root)

            code, output = self.run_cli(
                ["derive-text-coverage", str(archive_root), "--max-items", "10", "--dry-run", "--format", "json"]
            )
            result = json.loads(output)
            self.assertEqual(code, 1, output)
            self.assertFalse(result["ok"])
            self.assertEqual(result["lifecycle_action"], "derived_text_coverage_gate")
            self.assertEqual(result["coverage_gate"]["textual_candidate_count"], 4)
            self.assertEqual(result["coverage_gate"]["covered_textual_count"], 2)
            self.assertEqual(result["coverage_gate"]["missing_derived_text_count"], 1)
            self.assertEqual(result["coverage_gate"]["needs_password_or_encrypted_count"], 1)
            self.assertEqual(result["coverage_gate"]["manifest_quality_issue_count"], 2)
            self.assertEqual(result["manifest_quality"]["status"], "needs_review")
            self.assertEqual(result["manifest_quality"]["records_with_issues_count"], 2)
            self.assertEqual(result["manifest_quality"]["missing_tool_version_count"], 2)
            self.assertEqual(result["manifest_quality"]["missing_tool_name_count"], 2)
            self.assertEqual(result["manifest_quality"]["invalid_derivation_kind_count"], 2)
            self.assertEqual(result["manifest_quality"]["invalid_review_status_count"], 2)
            self.assertIn("tool_version_missing", result["manifest_quality"]["issue_sample"][0]["issues"])
            self.assertFalse(result["manifest_quality"]["closed_actions"]["derived_text_body_read"])
            self.assertFalse(result["manifest_quality"]["privacy_guards"]["local_absolute_paths_echoed"])
            self.assertIn("derived_text_manifest_quality_issues", result["blockers"])
            self.assertIn("derived_text_manifest_quality_needs_review", result["warnings"])
            self.assertEqual(result["completeness_signal"]["lifecycle_action"], "derived_text_completeness_signal")
            self.assertEqual(result["completeness_signal"]["state"], "manifest_scoped_incomplete")
            self.assertEqual(result["completeness_signal"]["scope_kind"], "manifest_scoped")
            self.assertFalse(result["completeness_signal"]["full_mirror_claimed"])
            self.assertFalse(result["completeness_signal"]["full_mirror_proof_present"])
            self.assertIn("objects/manifests/files.jsonl", result["completeness_signal"]["scope_source_of_truth"])
            self.assertIn("external_mailbox_fully_mirrored", result["completeness_signal"]["cannot_prove"])
            self.assertFalse(result["completeness_signal"]["closed_actions"]["external_workspace_scanned"])
            self.assertFalse(result["completeness_signal"]["closed_actions"]["provider_api_called"])
            self.assertEqual(result["missing_items"][0]["object_id"], f"sha256:{docx_digest}")
            self.assertEqual(result["missing_items"][0]["toolchain_family"], "office_open_xml_word")
            covered_by_derived_signal = [
                item for item in result["covered_sample"] if item["object_id"] == f"sha256:{prehashed_text_digest}"
            ][0]
            self.assertEqual(covered_by_derived_signal["textual_signal"], "derived_text_record_present")
            self.assertEqual(covered_by_derived_signal["toolchain_family"], "derived_text_present_unknown_source")
            self.assertFalse(result["missing_items"][0]["source_name_echoed"])
            self.assertFalse(result["privacy_guards"]["object_filenames_echoed"])
            self.assertFalse(result["closed_actions"]["source_file_body_read"])
            self.assertFalse(result["closed_actions"]["ocr_run"])
            self.assertEqual(result["would_change"], [])
            self.assertNotIn("private-client-contract", output)
            self.assertNotIn("password-needed", output)
            self.assertEqual(self._inventory(archive_root), before)

            code, output = self.run_cli(["derive-text", "coverage", str(archive_root), "--dry-run", "--format", "json"])
            self.assertEqual(code, 1, output)
            nested = json.loads(output)
            self.assertEqual(nested["coverage_gate"]["missing_derived_text_count"], 1)

